def role_from_query(role: str | None = None, x_role: str | None = None) -> str:
    return (x_role or role or "inspection").strip() or "inspection"


def file_type_tokens(file: dict[str, Any]) -> set[str]:
    raw_values = [file.get("fileType"), file.get("contentType")]
    file_name = str(file.get("fileName") or "")
    if "." in file_name:
        raw_values.append(file_name.rsplit(".", 1)[-1])
    tokens = {str(value).strip().lower() for value in raw_values if value}
    return tokens


def validate_upload_files(
    request: Request,
    files: list[dict[str, Any]],
    *,
    ndt: bool = False,
) -> JSONResponse | None:
    if not files:
        error = errors.NDT_REPORT_REQUIRED if ndt else errors.VALIDATION_ERROR
        return fail(error, request, message="上传文件不能为空。")
    allowed_types = ALLOWED_NDT_UPLOAD_TYPES if ndt else ALLOWED_UPLOAD_TYPES
    max_bytes = MAX_NDT_UPLOAD_BYTES if ndt else MAX_UPLOAD_BYTES
    for index, file in enumerate(files):
        file_name = file.get("fileName") or f"第 {index + 1} 个文件"
        try:
            file_size = int(file.get("fileSize") or 0)
        except (TypeError, ValueError):
            file_size = 0
        if file_size < 1:
            return fail(errors.VALIDATION_ERROR, request, message=f"{file_name} 文件大小必须大于 0。", data={"fileName": file_name})
        if file_size > max_bytes:
            error = errors.NDT_FILE_TOO_LARGE if ndt else errors.FILE_TOO_LARGE
            return fail(error, request, message=f"{file_name} 超过 {max_bytes // 1024 // 1024}MB 上传限制。", data={"fileName": file_name, "fileSize": file_size})
        if not (file_type_tokens(file) & allowed_types):
            error = errors.UNSUPPORTED_NDT_FILE_TYPE if ndt else errors.UNSUPPORTED_FILE_TYPE
            return fail(error, request, message=f"{file_name} 文件类型不支持。", data={"fileName": file_name, "fileType": file.get("fileType")})
        raw_ocr_options = file.get("ocrOptions")
        if raw_ocr_options is not None:
            if not isinstance(raw_ocr_options, dict):
                return fail(
                    errors.VALIDATION_ERROR,
                    request,
                    message=f"{file_name} 的 ocrOptions 必须是对象。",
                    data={"fileName": file_name},
                )
            ocr_options = dict(raw_ocr_options)
            provider = str(ocr_options.get("provider") or "").strip().lower()
            if provider and provider not in {"local", "mineru"}:
                return fail(
                    errors.VALIDATION_ERROR,
                    request,
                    message=f"{file_name} 的 OCR provider 仅支持 local 或 mineru。",
                    data={"fileName": file_name, "provider": provider},
                )
            if provider:
                ocr_options["provider"] = provider
            else:
                ocr_options.pop("provider", None)
            file["ocrOptions"] = ocr_options
    return None


NDT_ATOMIC_MATERIAL_CATEGORY = "无损检测资料"
NDT_ATOMIC_NODE_IDS = set(range(35, 43))


def validate_ndt_atomic_upload_files(request: Request, files: list[dict[str, Any]]) -> JSONResponse | None:
    for index, file in enumerate(files):
        if str(file.get("materialCategory") or "").strip() != NDT_ATOMIC_MATERIAL_CATEGORY:
            continue
        file_name = str(file.get("fileName") or f"第 {index + 1} 个文件")
        material_type_code = str(file.get("materialTypeCode") or "").strip()
        material_type_name = str(file.get("materialTypeName") or "").strip()
        raw_node_ids = file.get("nodeIds")
        if not material_type_code or not material_type_name:
            return fail(
                errors.VALIDATION_ERROR,
                request,
                message=f"{file_name} 必须选择资料类型。",
                data={"fileName": file_name},
            )
        if not isinstance(raw_node_ids, list) or not raw_node_ids:
            return fail(
                errors.VALIDATION_ERROR,
                request,
                message=f"{file_name} 至少选择一项适用业务规则。",
                data={"fileName": file_name},
            )
        try:
            node_ids = sorted({int(node_id) for node_id in raw_node_ids})
        except (TypeError, ValueError):
            node_ids = []
        if not node_ids or any(node_id not in NDT_ATOMIC_NODE_IDS for node_id in node_ids):
            return fail(
                errors.VALIDATION_ERROR,
                request,
                message=f"{file_name} 包含不适用的业务规则，请重新选择。",
                data={"fileName": file_name, "nodeIds": raw_node_ids},
            )
        file["nodeIds"] = node_ids
    return None


def safe_upload_file_name(file_name: str) -> str:
    normalized = str(file_name or "未命名文件").replace("\\", "/").split("/")[-1].strip()
    normalized = re.sub(r"[\x00-\x1f]", "", normalized)
    normalized = re.sub(r"[/:*?\"<>|]", "_", normalized)
    return normalized or "未命名文件"


def safe_relative_path(value: str | None, fallback_file_name: str) -> str:
    raw = str(value or fallback_file_name or "").replace("\\", "/").strip("/")
    parts = [safe_upload_file_name(part) for part in raw.split("/") if part and part not in {".", ".."}]
    return "/".join(parts[-8:]) or safe_upload_file_name(fallback_file_name)


def upload_file_type_tokens(file_name: str, content_type: str | None) -> set[str]:
    tokens = file_type_tokens({"fileName": file_name, "contentType": content_type, "fileType": content_type})
    suffix = Path(file_name).suffix.lower().lstrip(".")
    if suffix:
        tokens.add(suffix)
    guessed, _ = mimetypes.guess_type(file_name)
    if guessed:
        tokens.add(guessed.lower())
    return tokens


def first_form_value(fields: dict[str, list[str]], key: str, default: str = "") -> str:
    values = fields.get(key) or []
    return str(values[0]).strip() if values else default


def bounded_form_value(values: list[str], index: int, limit: int = 500) -> str:
    value = str(values[index]).strip() if index < len(values) else ""
    return value[:limit]


def display_upload_file_name(raw_name: str | None, original_file_name: str) -> str:
    display_name = safe_upload_file_name(raw_name or original_file_name)
    original_suffix = Path(original_file_name).suffix
    if original_suffix and not Path(display_name).suffix:
        display_name = f"{display_name}{original_suffix}"
    return display_name






def compact_rule_text(value: Any, limit: int = 900) -> str:
    text = re.sub(r"\n{3,}", "\n\n", str(value or "")).strip()
    return text[:limit]


def compact_plain_text(value: Any, limit: int = 2000) -> str:
    text = re.sub(r"[ \t]+", " ", str(value or "").strip())
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text[:limit]


def validated_plain_text(value: Any, *, limit: int, field_name: str) -> tuple[str | None, str | None]:
    raw = str(value or "").strip()
    normalized = re.sub(r"[ \t]+", " ", raw)
    normalized = re.sub(r"\n{3,}", "\n\n", normalized)
    if len(normalized) > limit:
        return None, f"{field_name}不能超过 {limit} 个字符。"
    return normalized, None


# 同一语义的说明字段在 121 个写端点里有 7 种命名（reason / comment / opinion /
# description / remark / text / content），9 个业务域内部还各自不一致。调用方写错名字时
# 请求返回 code 0、说明文本落 None——施工方写的整改说明就这么丢了，监检复审时看不到
# 对方解释了什么（M-7 / M-10）。统一契约成本太高且会破坏既有调用方，这里退而求其次：
# 收到「明显是说明文字、但不是本端点认的字段名」时明确拒绝，不再静默接受。
EXPLANATION_FIELD_ALIASES = (
    "comment",
    "content",
    "description",
    "explanation",
    "feedback",
    "message",
    "note",
    "notes",
    "opinion",
    "reason",
    "remark",
    "remarks",
    "response",
    "text",
)


def unrecognized_explanation_field_error(
    request: Request,
    body: dict[str, Any],
    accepted: tuple[str, ...],
) -> JSONResponse | None:
    """调用方用了别名而非本端点接受的说明字段名时拒绝，避免文本静默丢失。

    只在本端点一个都没收到时才报——同时传了正确字段就说明调用方知道该传什么，
    多带的键不影响业务，没必要拦。
    """
    if any(str(body.get(name) or "").strip() for name in accepted):
        return None
    misspelled = [
        name
        for name in EXPLANATION_FIELD_ALIASES
        if name not in accepted and str(body.get(name) or "").strip()
    ]
    if not misspelled:
        return None
    return fail(
        errors.VALIDATION_ERROR,
        request,
        message=(
            f"说明文字请放在 {accepted[0]} 字段。收到的 {'、'.join(misspelled)} "
            f"不是本接口接受的字段名，若直接忽略会让说明内容丢失。"
        ),
        data={"acceptedFields": list(accepted), "unrecognizedFields": misspelled},
    )


def split_business_rule_sentences(value: Any, limit: int = 12) -> list[str]:
    text = compact_plain_text(value, 3000)
    if not text:
        return []
    chunks = [
        item.strip(" ；;。.\n\t")
        for item in re.split(r"[；;。\n]+", text)
        if item.strip(" ；;。.\n\t")
    ]
    return chunks[:limit]


def extract_business_rule_terms(text: str, patterns: list[str], *, limit: int = 10) -> list[str]:
    terms: list[str] = []
    seen: set[str] = set()
    for pattern in patterns:
        for match in re.finditer(pattern, text):
            term = match.group(0).strip(" ，,；;。()（）")
            if term and term not in seen:
                seen.add(term)
                terms.append(term)
                if len(terms) >= limit:
                    return terms
    return terms


BUSINESS_RULE_EVIDENCE_PATTERNS = [
    r"[\u4e00-\u9fffA-Za-z0-9《》/（）()、]{0,16}(?:许可证|核准证|证书|报告|记录|方案|文件|图纸|印章|材料表|特性表|质量证明|合格证|照片|视频|铭牌|清单|报告曲线|检定证书)",
    r"(?:PQR|WPS|RT|UT|MT|PT|MTC|OCR)",
]
BUSINESS_RULE_EXTRACTION_PATTERNS = [
    r"(?:机构名称|单位名称|许可证号|证书编号|有效期|许可范围|核准项目代码|检测方法|管道级别|规格|型号|材质|批号|压力|温度|时间|保压时间|结论|签字|签章|数量|量程|精度|标准|焊缝编号|人员|日期)",
]
BUSINESS_RULE_ACTION_TERMS = ["核查", "审查", "检查", "抽查", "现场检查", "提取", "比对", "确认", "查询", "判断", "验证"]


def normalize_business_rule_class(value: Any) -> str:
    raw = compact_plain_text(value, 20).upper().replace("类", "")
    if raw in {"A", "B", "C", "C/B", "B/C"}:
        return "C/B" if raw in {"C/B", "B/C"} else raw
    if "A" in raw:
        return "A"
    if "B" in raw and "C" in raw:
        return "C/B"
    if "B" in raw:
        return "B"
    return "C" if raw else ""


def normalize_business_rule_source_fields(raw_rule: dict[str, Any]) -> dict[str, Any]:
    source_sequence = (
        raw_rule.get("sourceSequence")
        or raw_rule.get("sequence")
        or raw_rule.get("序号")
        or raw_rule.get("nodeId")
    )
    sequence = None
    if source_sequence is not None:
        seq_match = re.search(r"\d+", str(source_sequence))
        if seq_match:
            sequence = int(seq_match.group(0))
    category = compact_plain_text(
        raw_rule.get("inspectionCategory")
        or raw_rule.get("businessModule")
        or raw_rule.get("监检项目（大类）")
        or raw_rule.get("category"),
        120,
    )
    item = compact_plain_text(
        raw_rule.get("inspectionItem")
        or raw_rule.get("name")
        or raw_rule.get("title")
        or raw_rule.get("监检项目（内容）")
        or "未命名监检项目",
        180,
    )
    rule_class = normalize_business_rule_class(
        raw_rule.get("inspectionClass")
        or raw_rule.get("reviewClass")
        or raw_rule.get("类别")
        or raw_rule.get("class")
    )
    standard_text = compact_plain_text(
        raw_rule.get("standardText")
        or raw_rule.get("criteria")
        or raw_rule.get("判断准则 / 标准规范")
        or raw_rule.get("判断准则")
        or raw_rule.get("standard"),
        3000,
    )
    witness_text = compact_plain_text(
        raw_rule.get("witnessText")
        or raw_rule.get("checkMethod")
        or raw_rule.get("方法及内容 / 工作见证")
        or raw_rule.get("方法及内容")
        or raw_rule.get("工作见证")
        or raw_rule.get("method"),
        3000,
    )
    return {
        "sourceSequence": sequence,
        "inspectionCategory": category,
        "inspectionItem": item,
        "inspectionClass": rule_class,
        "standardText": standard_text,
        "witnessText": witness_text,
    }


def business_rule_node_ids_from_fields(fields: dict[str, Any], fallback: Any = None) -> list[int]:
    node_ids = parse_rule_node_ids(fallback)
    sequence = fields.get("sourceSequence")
    if sequence and int(sequence) not in node_ids:
        node_ids.insert(0, int(sequence))
    return node_ids or ([int(sequence)] if sequence else [])


def business_rule_name_from_nodes(node_ids: list[int], fallback: str) -> str:
    names: list[str] = []
    for node_id in node_ids:
        node = next(
            (
                item
                for item in repo.state.get("tree_nodes", [])
                if str(item.get("nodeId")) == str(node_id)
            ),
            None,
        )
        name = compact_plain_text((node or {}).get("name"), 120)
        if name and name not in names:
            names.append(name)
    if not names:
        return fallback
    if len(names) == 1:
        return names[0]
    return f"{names[0]}等 {len(names)} 个节点"


def make_business_rule_key(fields: dict[str, Any], raw_rule: dict[str, Any] | None = None) -> str:
    raw_key = compact_plain_text((raw_rule or {}).get("ruleKey"), 120)
    if raw_key:
        return raw_key
    sequence = fields.get("sourceSequence")
    if sequence:
        return f"inspection-rule-{int(sequence):02d}"
    digest = hashlib.sha1(fields.get("inspectionItem", "business-rule").encode("utf-8")).hexdigest()[:8]
    return f"inspection-rule-{digest}"


def compile_business_rule_execution(rule: dict[str, Any]) -> dict[str, Any]:
    standard_text = compact_plain_text(rule.get("standardText") or rule.get("criteria"), 3000)
    witness_text = compact_plain_text(rule.get("witnessText") or rule.get("checkMethod"), 3000)
    agent_thinking = compact_plain_text(rule.get("agentThinking"), 3000)
    toolchain_thinking = compact_plain_text(rule.get("toolchainThinking"), 3000)
    combined = "\n".join(
        part for part in [standard_text, witness_text, agent_thinking, toolchain_thinking] if part
    )
    method_sentences = split_business_rule_sentences(
        witness_text or agent_thinking or toolchain_thinking,
        limit=20,
    )
    standard_sentences = split_business_rule_sentences(standard_text, limit=12)
    action_steps = [
        sentence
        for sentence in method_sentences
        if any(term in sentence for term in BUSINESS_RULE_ACTION_TERMS) or sentence.startswith(("是否", "需", "应"))
    ] or method_sentences[:6]
    acceptance_criteria = [
        sentence
        for sentence in method_sentences + standard_sentences
        if any(term in sentence for term in ["是否", "不得", "不应", "应当", "应", "符合", "覆盖", "一致", "有效", "合格", "不少于", "不低于", "范围"])
    ][:10]
    required_evidence = extract_business_rule_terms(combined, BUSINESS_RULE_EVIDENCE_PATTERNS, limit=12)
    extraction_targets = extract_business_rule_terms(combined, BUSINESS_RULE_EXTRACTION_PATTERNS, limit=16)
    if not required_evidence:
        required_evidence = method_sentences[:3]
    human_confirmation = []
    if rule.get("inspectionClass") == "A" or rule.get("reviewClass") == "A":
        human_confirmation.append("A 类监检项目发布或审查结论需人工确认。")
    if any(term in witness_text for term in ["现场", "抽查", "照片", "视频", "目视", "实物"]):
        human_confirmation.append("涉及现场检查、抽查或影像证据时，AI 只做辅助核验，需监检人员确认现场事实。")
    if any(term in witness_text for term in ["如果不能", "必要时", "缺少", "不足", "不一致", "不能覆盖"]):
        human_confirmation.append("证据缺失、范围不覆盖或跨文件不一致时生成补充资料项或联络单。")
    return {
        "schemaVersion": "business-rule-execution-v1",
        "compiledAt": server_time(),
        "sourceFields": {
            "sourceRuleId": rule.get("sourceRuleId"),
            "sourceDocument": rule.get("sourceDocument") or rule.get("sourceFileName"),
            "sequence": rule.get("sourceSequence"),
            "inspectionCategory": rule.get("inspectionCategory") or rule.get("businessModule"),
            "inspectionItem": rule.get("inspectionItem") or rule.get("name"),
            "inspectionClass": rule.get("inspectionClass") or rule.get("reviewClass"),
            "standardText": standard_text,
            "witnessText": witness_text,
            "agentThinking": agent_thinking,
            "toolchainThinking": toolchain_thinking,
        },
        "requiredEvidence": required_evidence,
        "extractionTargets": extraction_targets,
        "verificationSteps": action_steps[:10],
        "acceptanceCriteria": acceptance_criteria,
        "humanConfirmation": human_confirmation or ["证据不足、OCR 置信度不足或结论影响放行时需人工确认。"],
        "promptContext": compact_rule_text(
            "\n".join(
                [
                    f"监检项目：{rule.get('inspectionItem') or rule.get('name')}",
                    f"类别：{rule.get('inspectionClass') or rule.get('reviewClass') or '-'}",
                    f"判断准则/标准规范：{standard_text or '-'}",
                    f"方法及内容/工作见证：{witness_text or '-'}",
                    f"Agent思考方式：{agent_thinking or '-'}",
                    f"工具集调用思考：{toolchain_thinking or '-'}",
                ]
            ),
            1600,
        ),
    }


def normalize_business_rule_version_record(
    raw_rule: dict[str, Any],
    *,
    import_version: str | None = None,
    imported_at: str | None = None,
    force_status: str | None = None,
) -> dict[str, Any]:
    now = imported_at or server_time()
    fields = normalize_business_rule_source_fields(raw_rule)
    rule_key = make_business_rule_key(fields, raw_rule)
    source_sequence = fields.get("sourceSequence")
    version = compact_plain_text(raw_rule.get("version"), 160)
    if not version:
        suffix = import_version or f"draft-{now[:16].replace('-', '').replace(':', '').replace(' ', '-')}"
        version = f"{rule_key}-{suffix}"
    rule_id = compact_plain_text(raw_rule.get("id"), 120) or f"RULE-{uuid4().hex[:10].upper()}"
    status = normalize_rule_status(raw_rule.get("status"), default="草稿")
    if force_status:
        status = force_status
    node_ids = business_rule_node_ids_from_fields(fields, raw_rule.get("nodeIds") or raw_rule.get("nodeId"))
    record = {
        **raw_rule,
        **fields,
        "id": rule_id,
        "name": business_rule_name_from_nodes(node_ids, fields["inspectionItem"]),
        "ruleKey": rule_key,
        "version": version,
        "status": status,
        "nodeIds": node_ids,
        "reviewClass": fields["inspectionClass"],
        "criteria": fields["standardText"],
        "checkMethod": fields["witnessText"],
        "description": compact_rule_text(fields["witnessText"] or fields["standardText"] or fields["inspectionItem"], 500),
        "promptVersion": compact_plain_text(raw_rule.get("promptVersion"), 120) or f"prompt-{rule_key}",
        "outputSchemaVersion": compact_plain_text(raw_rule.get("outputSchemaVersion"), 120) or "schema-review-v1.3",
        "schemaVersion": compact_plain_text(raw_rule.get("schemaVersion"), 80) or "business-rule-version-v1",
        "updatedAt": now,
        "actions": raw_rule.get("actions") or ["knowledge:view", "knowledge:manage"],
        "revision": int(raw_rule.get("revision") or 1),
    }
    if source_sequence is not None:
        record["sourceSequence"] = int(source_sequence)
    if raw_rule.get("sourceFileName"):
        record["sourceFileName"] = raw_rule["sourceFileName"]
    if raw_rule.get("importedAt") or imported_at:
        record["importedAt"] = raw_rule.get("importedAt") or imported_at
    record["aiExecution"] = compile_business_rule_execution(record)
    return record


def extract_markdown_rule_field(section: str, title: str) -> str:
    marker = re.escape(title)
    pattern = rf"\*\*{marker}\*\*\s*(.*?)(?=\n\*\*|\n###\s+R\d+|\Z)"
    match = re.search(pattern, section, re.DOTALL)
    return compact_rule_text(match.group(1) if match else "")


def parse_markdown_business_rules(
    text: str,
    *,
    source_file_name: str,
    import_version: str,
    imported_at: str,
) -> list[dict[str, Any]]:
    sections = list(re.finditer(r"^###\s+(R\d+)\s*[｜|]\s*(.+?)\s*$", text, re.MULTILINE))
    parsed: list[dict[str, Any]] = []
    for index, match in enumerate(sections):
        source_rule_id = match.group(1).upper()
        name = match.group(2).strip()
        section_start = match.end()
        section_end = sections[index + 1].start() if index + 1 < len(sections) else len(text)
        section = text[section_start:section_end]
        meta_line = next(
            (line.strip("| ") for line in section.splitlines() if line.startswith("| 来源文档")),
            "",
        )
        source_document = ""
        business_module = ""
        review_class = ""
        source_sequence = None
        if meta_line:
            for part in [part.strip() for part in meta_line.split("|")]:
                if part.startswith("来源文档"):
                    source_document = part.removeprefix("来源文档").strip()
                elif part.startswith("原位置"):
                    seq_match = re.search(r"\d+", part)
                    if seq_match:
                        source_sequence = int(seq_match.group(0))
                elif part.startswith("业务模块"):
                    business_module = part.removeprefix("业务模块").strip()
                elif part.startswith("类别"):
                    review_class = part.removeprefix("类别").strip()
        criteria = extract_markdown_rule_field(section, "判断准则（原文）") or extract_markdown_rule_field(section, "标准规范（原文）")
        check_method = (
            extract_markdown_rule_field(section, "方法（原文）")
            or extract_markdown_rule_field(section, "方法及内容（原文）")
            or extract_markdown_rule_field(section, "工作见证（原文）")
        )
        agent_thinking = extract_markdown_rule_field(section, "Agent思考方式（新增）")
        toolchain_thinking = extract_markdown_rule_field(section, "工具集调用思考（新增）")
        rule_number = int(source_rule_id.removeprefix("R"))
        node_id = source_sequence or rule_number
        rule_key = f"engineering-inspection-{source_rule_id.lower()}"
        raw_record = {
            "id": f"RULE-IMPORT-{source_rule_id}-{uuid4().hex[:6].upper()}",
            "name": name,
            "ruleKey": rule_key,
            "version": f"{rule_key}-{import_version}",
            "status": "草稿",
            "nodeIds": [node_id],
            "inspectionCategory": business_module,
            "inspectionItem": name,
            "inspectionClass": review_class or "C",
            "standardText": criteria,
            "witnessText": check_method,
            "severity": "medium" if "A" in review_class else "low",
            "reviewClass": review_class or "C",
            "promptVersion": f"prompt-engineering-inspection-{import_version}",
            "outputSchemaVersion": "schema-review-v1.3",
            "sourceRuleId": source_rule_id,
            "sourceDocument": source_document or source_file_name,
            "sourceSequence": node_id,
            "businessModule": business_module,
            "criteria": criteria,
            "checkMethod": check_method,
            "agentThinking": agent_thinking,
            "toolchainThinking": toolchain_thinking,
            "description": compact_rule_text(agent_thinking or check_method or criteria or name, 500),
            "requiredEvidence": [
                f"{source_document or source_file_name} 序号{node_id}：{name}",
                "与 nodeIds 绑定的项目文件、OCR 字段、原件/复印件、签字盖章、报告结论和证据链接",
            ],
            "humanConfirmation": {
                "requiredWhen": [
                    "证据缺失、OCR 置信度不足或原件/复印件真实性无法自动确认",
                    "跨文件主体名称、规格型号、批号、焊缝编号、报告编号或结论不一致",
                ]
            },
            "sourceFileName": source_file_name,
            "parserVersion": "business-rule-importer-v1",
            "schemaVersion": "business-rule-version-v1",
            "importedAt": imported_at,
            "updatedAt": imported_at,
            "actions": ["knowledge:view", "knowledge:manage"],
            "revision": 1,
        }
        parsed.append(
            normalize_business_rule_version_record(
                raw_record,
                import_version=import_version,
                imported_at=imported_at,
                force_status="草稿",
            )
        )
    return parsed


def normalize_imported_rule_record(
    raw_rule: dict[str, Any],
    *,
    source_file_name: str,
    import_version: str,
    imported_at: str,
) -> dict[str, Any]:
    source_rule_id = str(raw_rule.get("sourceRuleId") or raw_rule.get("ruleId") or raw_rule.get("id") or "").strip()
    normalized = normalize_business_rule_version_record(
        {
            **raw_rule,
            "sourceRuleId": source_rule_id or raw_rule.get("ruleKey"),
            "sourceFileName": source_file_name,
            "parserVersion": raw_rule.get("parserVersion") or "business-rule-importer-v1",
        },
        import_version=import_version,
        imported_at=imported_at,
        force_status="草稿",
    )
    normalized["importedAt"] = imported_at
    return normalized


def parse_structured_business_rules(
    text: str,
    *,
    source_file_name: str,
    import_version: str,
    imported_at: str,
) -> list[dict[str, Any]]:
    try:
        payload = json.loads(text) if source_file_name.lower().endswith(".json") else yaml.safe_load(text)
    except (ValueError, UnicodeDecodeError):
        payload = None
    raw_rules: list[Any] = []
    if isinstance(payload, dict):
        candidate = payload.get("ruleSets") or payload.get("rules") or payload.get("items")
        raw_rules = candidate if isinstance(candidate, list) else []
    elif isinstance(payload, list):
        raw_rules = payload
    return [
        normalize_imported_rule_record(
            rule,
            source_file_name=source_file_name,
            import_version=import_version,
            imported_at=imported_at,
        )
        for rule in raw_rules
        if isinstance(rule, dict)
    ]


def parse_docx_business_rules(
    data: bytes,
    *,
    source_file_name: str,
    import_version: str,
    imported_at: str,
) -> list[dict[str, Any]]:
    try:
        with zipfile.ZipFile(io.BytesIO(data)) as archive:
            document_xml = archive.read("word/document.xml")
    except Exception:
        return []
    try:
        root = ET.fromstring(document_xml)
    except Exception:
        return []
    ns = {"w": "http://schemas.openxmlformats.org/wordprocessingml/2006/main"}
    rows: list[list[str]] = []
    for tr in root.findall(".//w:tbl/w:tr", ns):
        cells: list[str] = []
        for tc in tr.findall("./w:tc", ns):
            paragraphs = []
            for paragraph in tc.findall(".//w:p", ns):
                paragraph_text = "".join(node.text or "" for node in paragraph.findall(".//w:t", ns)).strip()
                if paragraph_text:
                    paragraphs.append(paragraph_text)
            text = compact_plain_text("\n".join(paragraphs), 4000)
            cells.append(text)
        if any(cells):
            rows.append(cells)
    if len(rows) < 2:
        return []
    headers = rows[0]
    normalized_headers = [re.sub(r"\s+", "", header) for header in headers]
    if not any("监检项目" in header for header in normalized_headers):
        return []

    def cell(row: list[str], *names: str) -> str:
        for name in names:
            normalized_name = re.sub(r"\s+", "", name)
            for index, header in enumerate(normalized_headers):
                if normalized_name == header or normalized_name in header:
                    return row[index] if index < len(row) else ""
        return ""

    parsed: list[dict[str, Any]] = []
    for row in rows[1:]:
        if not any(item.strip() for item in row):
            continue
        raw_rule = {
            "sequence": cell(row, "序号"),
            "inspectionCategory": cell(row, "监检项目（大类）", "监检项目大类"),
            "inspectionItem": cell(row, "监检项目（内容）", "监检项目内容"),
            "inspectionClass": cell(row, "类别"),
            "standardText": cell(row, "判断准则 / 标准规范", "判断准则/标准规范"),
            "witnessText": cell(row, "方法及内容 / 工作见证", "方法及内容/工作见证"),
            "sourceFileName": source_file_name,
            "sourceDocument": source_file_name,
            "parserVersion": "business-rule-docx-table-v1",
        }
        if not raw_rule["inspectionItem"]:
            continue
        parsed.append(
            normalize_business_rule_version_record(
                raw_rule,
                import_version=import_version,
                imported_at=imported_at,
                force_status="草稿",
            )
        )
    return parsed


def parse_business_rule_upload(
    upload: dict[str, Any],
    *,
    import_version: str,
    imported_at: str,
) -> tuple[list[dict[str, Any]], str | None]:
    source_file_name = safe_upload_file_name(upload["fileName"])
    data = upload["data"]
    content_type = str(upload.get("contentType") or mimetypes.guess_type(source_file_name)[0] or "application/octet-stream")
    if not data:
        return [], "文件内容为空"
    if len(data) > MAX_UPLOAD_BYTES:
        return [], f"超过 {MAX_UPLOAD_BYTES // 1024 // 1024}MB 上传限制"
    if not (upload_file_type_tokens(source_file_name, content_type) & ALLOWED_RULE_UPLOAD_TYPES):
        return [], "业务规则只支持 Word、Markdown、YAML、JSON 或 TXT"
    suffix = Path(source_file_name).suffix.lower()
    if suffix == ".docx":
        rules = parse_docx_business_rules(
            data,
            source_file_name=source_file_name,
            import_version=import_version,
            imported_at=imported_at,
        )
        if not rules:
            return [], "未解析到业务规则，请使用包含“序号、监检项目（大类）、监检项目（内容）、类别、判断准则 / 标准规范、方法及内容 / 工作见证”的 Word 表格"
        return rules, None
    text = data.decode("utf-8", errors="replace")
    rules = (
        parse_structured_business_rules(
            text,
            source_file_name=source_file_name,
            import_version=import_version,
            imported_at=imported_at,
        )
        if suffix in {".yaml", ".yml", ".json"}
        else []
    )
    if not rules:
        rules = parse_markdown_business_rules(
            text,
            source_file_name=source_file_name,
            import_version=import_version,
            imported_at=imported_at,
        )
    if not rules:
        return [], "未解析到业务规则，请使用 Word 六列表格、rules.yaml 的 ruleSets 或 Markdown 的“### R01｜规则名称”格式"
    return rules, None


async def parse_multipart_uploads(request: Request) -> tuple[dict[str, list[str]], list[dict[str, Any]], JSONResponse | None]:
    content_type = request.headers.get("content-type") or request.headers.get("Content-Type") or ""
    if "multipart/form-data" not in content_type.lower():
        return {}, [], fail(errors.VALIDATION_ERROR, request, message="请使用 multipart/form-data 上传知识库文件。")
    body = await request.body()
    if not body:
        return {}, [], fail(errors.VALIDATION_ERROR, request, message="上传内容不能为空。")
    try:
        message = BytesParser(policy=policy.default).parsebytes(
            f"Content-Type: {content_type}\r\nMIME-Version: 1.0\r\n\r\n".encode() + body
        )
    except Exception as exc:
        return {}, [], fail(errors.VALIDATION_ERROR, request, message=f"上传表单解析失败：{exc}")
    if not message.is_multipart():
        return {}, [], fail(errors.VALIDATION_ERROR, request, message="上传表单缺少 multipart 边界。")
    fields: dict[str, list[str]] = {}
    uploads: list[dict[str, Any]] = []
    for part in message.iter_parts():
        if part.get_content_disposition() != "form-data":
            continue
        field_name = part.get_param("name", header="content-disposition") or ""
        file_name = part.get_filename()
        payload = part.get_payload(decode=True) or b""
        if file_name:
            uploads.append(
                {
                    "fieldName": field_name,
                    "fileName": safe_upload_file_name(file_name),
                    "contentType": part.get_content_type(),
                    "data": payload,
                }
            )
        else:
            fields.setdefault(field_name, []).append(payload.decode("utf-8", errors="replace"))
    return fields, uploads, None


def multipart_upload_fingerprint(uploads: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return [
        {
            "fieldName": upload.get("fieldName"),
            "fileName": upload.get("fileName"),
            "contentType": upload.get("contentType"),
            "size": len(upload.get("data") or b""),
            "sha256": hashlib.sha256(upload.get("data") or b"").hexdigest(),
        }
        for upload in uploads
    ]


def knowledge_source_for_import(
    source_id: str | None,
    source_name: str | None = None,
    source_type: str | None = None,
    source_version: str | None = None,
    source_status: str | None = None,
    vector_status: str | None = None,
) -> dict[str, Any]:
    effective_source_id = source_id or STANDARD_RULES_SOURCE_ID
    source = repo.find_one("knowledge_sources", effective_source_id)
    if source:
        return source
    source = {
        "id": effective_source_id,
        "name": source_name or STANDARD_LIBRARY_SOURCE_NAME,
        "sourceType": source_type or "standard",
        "version": source_version or f"upload-{server_time()[:10]}",
        "status": source_status or "启用",
        "fileCount": 0,
        "chunkCount": 0,
        "vectorStatus": vector_status or "待向量化",
        "updatedAt": server_time(),
        "actions": ["knowledge:view", "knowledge:manage", "knowledge:reindex"],
        "revision": 1,
    }
    repo.state["knowledge_sources"].insert(0, source)
    return source


def iter_rules_standard_files() -> list[Path]:
    if not RULES_STANDARDS_ROOT.exists():
        return []
    files = []
    for path in RULES_STANDARDS_ROOT.rglob("*"):
        if not path.is_file() or path.name.startswith("."):
            continue
        content_type = mimetypes.guess_type(path.name)[0] or "application/octet-stream"
        if upload_file_type_tokens(path.name, content_type) & ALLOWED_KNOWLEDGE_UPLOAD_TYPES:
            files.append(path)
    return sorted(files, key=lambda item: str(item.relative_to(RULES_STANDARDS_ROOT)).lower())


def iter_rules_import_files() -> list[dict[str, Any]]:
    files = [
        {"path": path, "contextType": "standard_reference", "label": "standard"}
        for path in iter_rules_standard_files()
    ]
    if RULES_BUSINESS_RULES_PATH.exists() and RULES_BUSINESS_RULES_PATH.is_file():
        files.append({"path": RULES_BUSINESS_RULES_PATH, "contextType": "business_rule_context", "label": "business_rule_context"})
    return sorted(files, key=lambda item: str(item["path"].relative_to(WORKSPACE_ROOT)).lower())


def existing_knowledge_file_by_hash(source_id: str, file_hash: str) -> dict[str, Any] | None:
    for file in repo.state.get("knowledge_files", []):
        if file.get("sourceId") != source_id:
            continue
        version = repo.find_one("versions", file.get("documentVersionId")) or {}
        if version.get("hash") == file_hash:
            return file
    return None


def sync_knowledge_source_counts(source: dict[str, Any]) -> None:
    source_files = [item for item in repo.state.get("knowledge_files", []) if item.get("sourceId") == source.get("id")]
    source["fileCount"] = len(source_files)
    source["chunkCount"] = sum(int(item.get("chunkCount") or 0) for item in source_files)
    if source_files:
        if all(item.get("vectorStatus") == "已向量化" for item in source_files):
            source["vectorStatus"] = "已向量化"
        elif any(item.get("vectorStatus") == "向量化中" for item in source_files):
            source["vectorStatus"] = "向量化中"
        elif any(item.get("vectorStatus") == "向量化失败" for item in source_files):
            source["vectorStatus"] = "部分失败"
        else:
            source["vectorStatus"] = "待向量化"
    else:
        source["vectorStatus"] = source.get("vectorStatus") or "待向量化"
    source["updatedAt"] = server_time()
    bump_record_revision(source)


def stable_knowledge_record_seed(source_id: str, relative_path: str) -> str:
    return hashlib.sha1(f"{source_id}:{relative_path}".encode()).hexdigest()[:10].upper()


def resolve_knowledge_file_id(file_id: str) -> str:
    if repo.find_one("knowledge_files", file_id):
        return file_id
    for source in repo.state.get("knowledge_sources", []):
        aliases = source.get("fileIdAliases") or {}
        if not isinstance(aliases, dict):
            continue
        resolved = aliases.get(file_id)
        if resolved and repo.find_one("knowledge_files", str(resolved)):
            return str(resolved)
    return file_id


def current_business_rule_for_node(
    node_id: int,
    *,
    business_pack_id: str | None = None,
) -> dict[str, Any] | None:
    candidates = []
    for rule in repo.state.get("rule_versions", []):
        if normalize_rule_status(rule.get("status")) != "已发布":
            continue
        if int(node_id) not in set(parse_rule_node_ids(rule.get("nodeIds"))):
            continue
        if business_pack_id and rule.get("businessPackId") not in {None, "", business_pack_id}:
            continue
        candidates.append(rule)
    candidates.sort(
        key=lambda item: str(item.get("publishedAt") or item.get("updatedAt") or item.get("importedAt") or ""),
        reverse=True,
    )
    return candidates[0] if candidates else None


def knowledge_file_is_business_rule(file: dict[str, Any] | None) -> bool:
    if not file:
        return False
    source = repo.find_one("knowledge_sources", file.get("sourceId"))
    return (source or {}).get("sourceType") == "rule" or file.get("sourceType") == "rule"


def knowledge_file_source_type(file: dict[str, Any] | None) -> str:
    if not file:
        return ""
    source = repo.find_one("knowledge_sources", file.get("sourceId")) or {}
    return str(file.get("sourceType") or source.get("sourceType") or "")


def remove_knowledge_file_records(file: dict[str, Any]) -> dict[str, int]:
    file_id = str(file.get("id") or "")
    document_id = str(file.get("documentId") or "")
    version_ids = {
        str(item.get("id"))
        for item in repo.state.get("versions", [])
        if document_id and item.get("documentId") == document_id and item.get("id")
    }
    if file.get("documentVersionId"):
        version_ids.add(str(file["documentVersionId"]))
    chunk_ids = {
        str(item.get("id"))
        for item in repo.state.get("knowledge_chunks", [])
        if item.get("fileId") == file_id
        or (document_id and item.get("documentId") == document_id)
        or str(item.get("documentVersionId") or "") in version_ids
    }

    before = {
        "files": len(repo.state.get("knowledge_files", [])),
        "documents": len(repo.state.get("documents", [])),
        "versions": len(repo.state.get("versions", [])),
        "chunks": len(repo.state.get("knowledge_chunks", [])),
        "vectors": len(repo.state.get("knowledge_vectors", [])),
        "tasks": len(repo.state.get("knowledge_tasks", [])),
        "evidenceLinks": len(repo.state.get("evidence_links", [])),
    }
    repo.state["knowledge_files"] = [
        item for item in repo.state.get("knowledge_files", []) if item.get("id") != file_id
    ]
    repo.state["documents"] = [
        item for item in repo.state.get("documents", []) if item.get("id") != document_id
    ]
    repo.state["versions"] = [
        item
        for item in repo.state.get("versions", [])
        if not (document_id and item.get("documentId") == document_id) and str(item.get("id") or "") not in version_ids
    ]
    repo.state["knowledge_chunks"] = [
        item
        for item in repo.state.get("knowledge_chunks", [])
        if item.get("fileId") != file_id
        and not (document_id and item.get("documentId") == document_id)
        and str(item.get("documentVersionId") or "") not in version_ids
    ]
    repo.state["knowledge_vectors"] = [
        item
        for item in repo.state.get("knowledge_vectors", [])
        if item.get("fileId") != file_id
        and str(item.get("chunkId") or "") not in chunk_ids
        and not (document_id and item.get("documentId") == document_id)
        and str(item.get("documentVersionId") or "") not in version_ids
    ]
    repo.state["knowledge_tasks"] = [
        item
        for item in repo.state.get("knowledge_tasks", [])
        if item.get("targetId") != file_id
        and not (document_id and item.get("documentId") == document_id)
        and str(item.get("documentVersionId") or "") not in version_ids
    ]
    repo.state["evidence_links"] = [
        item
        for item in repo.state.get("evidence_links", [])
        if item.get("fileId") != file_id
        and item.get("knowledgeFileId") != file_id
        and not (document_id and item.get("documentId") == document_id)
        and str(item.get("documentVersionId") or "") not in version_ids
        and str(item.get("chunkId") or item.get("knowledgeChunkId") or "") not in chunk_ids
    ]
    after = {
        "files": len(repo.state.get("knowledge_files", [])),
        "documents": len(repo.state.get("documents", [])),
        "versions": len(repo.state.get("versions", [])),
        "chunks": len(repo.state.get("knowledge_chunks", [])),
        "vectors": len(repo.state.get("knowledge_vectors", [])),
        "tasks": len(repo.state.get("knowledge_tasks", [])),
        "evidenceLinks": len(repo.state.get("evidence_links", [])),
    }
    return {key: before[key] - after[key] for key in before}


def knowledge_task_is_business_rule(task: dict[str, Any] | None) -> bool:
    if not task:
        return False
    target_type = str(task.get("targetType") or "").lower()
    target_id = str(task.get("targetId") or "")
    if target_type in {"file", "knowledgefile", "knowledge_file"}:
        return knowledge_file_is_business_rule(repo.find_one("knowledge_files", target_id))
    if target_type in {"source", "knowledgesource", "knowledge_source"}:
        source = repo.find_one("knowledge_sources", target_id)
        return (source or {}).get("sourceType") == "rule"
    return False


def store_knowledge_upload(
    *,
    source_id: str,
    file_id: str,
    file_name: str,
    content_type: str,
    data: bytes,
) -> tuple[str, str]:
    object_name = f"knowledge/{source_id}/{file_id}/{file_name}"
    stored_url = object_storage.put_bytes("documents", object_name, data, content_type=content_type)
    if stored_url:
        return object_name, "documents"
    target_dir = KNOWLEDGE_UPLOAD_ROOT / source_id / file_id
    target_dir.mkdir(parents=True, exist_ok=True)
    target_path = target_dir / file_name
    target_path.write_bytes(data)
    return f"local://{target_path.relative_to(WORKSPACE_ROOT)}", "local"


def knowledge_file_original_context(request: Request, file_id: str):
    file_id = resolve_knowledge_file_id(file_id)
    file = repo.find_one("knowledge_files", file_id)
    if not file:
        return None, None, None, fail(errors.NOT_FOUND, request)
    if knowledge_file_is_business_rule(file):
        return None, None, None, fail(errors.NOT_FOUND, request, message="业务规则不作为知识文件展示。")
    scope_error = scope_error_for_record(request, file)
    if scope_error:
        return None, None, None, scope_error
    document = repo.find_one("documents", file.get("documentId"))
    if not document:
        return file, None, None, fail(errors.NOT_FOUND, request, message="未找到关联原始文档。")
    version = repo.current_version(document["id"])
    if not version:
        return file, document, None, fail(errors.NOT_FOUND, request, message="未找到原始文档版本。")
    return file, document, version, None


def local_storage_path(storage_key: str | None) -> Path | None:
    raw = str(storage_key or "")
    if not raw.startswith("local://"):
        return None
    relative = raw.removeprefix("local://").lstrip("/")
    target = (WORKSPACE_ROOT / relative).resolve()
    try:
        target.relative_to(WORKSPACE_ROOT.resolve())
    except ValueError:
        return None
    return target


def knowledge_file_original_payload(request: Request, file_id: str, document: dict[str, Any]) -> dict[str, Any]:
    preview = repo.document_preview(document)
    download = repo.document_download(document)
    inline_url = str(request.url_for("knowledge_file_original", file_id=file_id)) + "?disposition=inline"
    attachment_url = str(request.url_for("knowledge_file_original", file_id=file_id)) + "?disposition=attachment"
    return {
        "preview": {
            **preview,
            "url": inline_url,
            "sourceUrl": preview.get("url"),
        },
        "download": {
            **download,
            "url": attachment_url,
            "sourceUrl": download.get("url"),
        },
    }


def create_imported_knowledge_records(
    *,
    source: dict[str, Any],
    file_name: str,
    content_type: str,
    data: bytes,
    relative_path: str,
    original_file_name: str,
    context_description: str,
    uploader_name: str,
    record_seed: str | None = None,
    project_id: str | None = None,
    project_name: str | None = None,
    node_id: int | None = None,
    node_name: str | None = None,
    storage_key_override: str | None = None,
    storage_bucket_override: str | None = None,
    context_type: str | None = None,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any], dict[str, Any], dict[str, Any]]:
    now = server_time()
    file_hash = hashlib.sha256(data).hexdigest()
    source_id = str(source["id"])
    seed = (record_seed or uuid4().hex[:10]).upper()[:10]
    document_id = f"KDOC-{seed}"
    version_id = f"KDV-{seed}-V1"
    file_id = f"KF-KB-{seed}"
    if storage_key_override:
        storage_key, storage_bucket = storage_key_override, storage_bucket_override or "local"
    else:
        storage_key, storage_bucket = store_knowledge_upload(
            source_id=source_id,
            file_id=file_id,
            file_name=file_name,
            content_type=content_type,
            data=data,
        )
    file_type = Path(file_name).suffix.lower().lstrip(".") or content_type
    document = {
        "id": document_id,
        "projectId": project_id,
        "businessPackId": DEFAULT_BUSINESS_PACK_ID,
        "materialTypeCode": "project_file" if project_id else "standard_reference",
        "fileName": file_name,
        "originalFileName": original_file_name,
        "fileType": file_type,
        "sourceOrgName": source.get("name") or "知识库导入",
        "contextDescription": context_description,
        "uploaderName": uploader_name,
        "currentVersionId": version_id,
        "fileStatus": "已上传",
        "currentOcrStatus": "识别中",
        "updatedAt": now,
        "actions": ["file:view", "file:preview", "file:download"],
    }
    version = {
        "id": version_id,
        "documentId": document_id,
        "versionNo": "V1",
        "hash": file_hash,
        "fileSize": len(data),
        "fileName": file_name,
        "originalFileName": original_file_name,
        "contextDescription": context_description,
        "storageKey": storage_key,
        "storageBucket": storage_bucket,
        "ocrStatus": "识别中",
        "sliceStatus": "未切片",
        "vectorStatus": "待向量化",
        "uploaderName": uploader_name,
        "uploadTime": now,
        "isCurrent": True,
    }
    knowledge_file = {
        "id": file_id,
        "fileName": file_name,
        "originalFileName": original_file_name,
        "sourceId": source_id,
        "sourceName": source.get("name") or source_id,
        "sourceType": source.get("sourceType"),
        "contextDescription": context_description,
        "projectId": project_id,
        "projectName": project_name or "",
        "nodeId": node_id,
        "nodeName": node_name or "",
        "documentId": document_id,
        "documentVersionId": version_id,
        "ocrStatus": "识别中",
        "sliceStatus": "未切片",
        "vectorStatus": "待向量化",
        "chunkCount": 0,
        "vectorCount": 0,
        "updatedAt": now,
        "sourceRelativePath": relative_path,
        "contextType": context_type or "standard_reference",
        "embeddingModel": OFFLINE_EMBEDDING_MODEL,
        "indexVersion": STANDARD_INDEX_VERSION,
        "actions": ["knowledge:view", "knowledge:reindex"],
    }
    task = {
        "id": f"KT-{seed}",
        "taskType": "ocr",
        "targetType": "file",
        "targetId": file_id,
        "targetName": file_name,
        "documentId": document_id,
        "documentVersionId": version_id,
        "projectId": project_id,
        "nodeId": node_id,
        "status": "排队中",
        "progress": 0,
        "createdAt": now,
        "updatedAt": now,
        "revision": 1,
        "actions": ["knowledge:task-retry"],
    }
    return document, version, knowledge_file, task, {"storageKey": storage_key, "storageBucket": storage_bucket}


def reset_knowledge_file_derived_index(file_id: str) -> None:
    repo.state["knowledge_chunks"] = [
        item for item in repo.state.get("knowledge_chunks", []) if item.get("fileId") != file_id
    ]
    repo.state["knowledge_vectors"] = [
        item for item in repo.state.get("knowledge_vectors", []) if item.get("fileId") != file_id
    ]


def knowledge_ocr_storage_key(version: dict[str, Any]) -> str:
    storage_key = str(version.get("storageKey") or version.get("id") or "")
    if parse_storage_url(storage_key) or storage_key.startswith(("local://", "mock://", "http://", "https://")):
        return storage_key
    storage_bucket = str(version.get("storageBucket") or "")
    if storage_bucket and storage_key:
        return f"minio://{storage_bucket}/{storage_key}"
    return storage_key


def migrate_local_knowledge_version_to_object_storage(
    file: dict[str, Any],
    document: dict[str, Any],
    version: dict[str, Any],
) -> dict[str, Any] | None:
    storage_key = str(version.get("storageKey") or "")
    if not storage_key.startswith("local://") or not object_storage.enabled:
        return None
    local_path = local_storage_path(storage_key)
    if not local_path or not local_path.is_file():
        return None
    file_name = str(
        version.get("fileName")
        or document.get("fileName")
        or file.get("fileName")
        or local_path.name
        or version.get("id")
        or "source.bin"
    )
    object_file_name = Path(file_name).name or local_path.name
    object_name = f"knowledge/{file.get('sourceId') or 'unknown-source'}/{file['id']}/{object_file_name}"
    content_type = (
        repo.document_content_type(document)
        or mimetypes.guess_type(object_file_name)[0]
        or "application/octet-stream"
    )
    stored_url = object_storage.put_bytes(
        "documents",
        object_name,
        local_path.read_bytes(),
        content_type=content_type,
    )
    if not stored_url:
        return None
    now = server_time()
    version["storageKey"] = object_name
    version["storageBucket"] = "documents"
    version["fileSize"] = version.get("fileSize") or local_path.stat().st_size
    document["updatedAt"] = now
    file["updatedAt"] = now
    bump_record_revision(file)
    return {
        "storageMigrated": True,
        "fromStorageKey": storage_key,
        "storageKey": object_name,
        "storageBucket": "documents",
    }


def dispatch_knowledge_file_ocr_pipeline(file: dict[str, Any], *, reason: str) -> dict[str, Any]:
    document = repo.find_one("documents", file.get("documentId"))
    version = repo.find_one("versions", file.get("documentVersionId"))
    if not document or not version:
        raise ValueError("missing_document_version")
    file_id = str(file["id"])
    now = server_time()
    reset_knowledge_file_derived_index(file_id)
    storage_migration = migrate_local_knowledge_version_to_object_storage(file, document, version)
    document["currentOcrStatus"] = "识别中"
    document["updatedAt"] = now
    version["ocrStatus"] = "识别中"
    version["sliceStatus"] = "未切片"
    version["vectorStatus"] = "待向量化"
    file["ocrStatus"] = "识别中"
    file["sliceStatus"] = "未切片"
    file["vectorStatus"] = "待向量化"
    file["chunkCount"] = 0
    file["vectorCount"] = 0
    file["updatedAt"] = now
    bump_record_revision(file)
    task = repo.upsert_knowledge_task(
        task_type="ocr",
        target_id=file_id,
        target_name=str(file.get("fileName") or document.get("fileName") or file_id),
        document_id=document["id"],
        version_id=version["id"],
    )
    task["documentId"] = document["id"]
    task["documentVersionId"] = version["id"]
    task["targetName"] = str(file.get("fileName") or document.get("fileName") or task.get("targetName") or file_id)
    task.pop("finishedAt", None)
    task.pop("errorMessage", None)
    repo.append_task_log(task, "info", reason)
    if storage_migration:
        repo.append_task_log(task, "info", f"源文件已迁移到对象存储：{storage_migration['storageBucket']}/{storage_migration['storageKey']}")
    dispatch = task_dispatcher.dispatch_parse_document(
        document["id"],
        version["id"],
        knowledge_ocr_storage_key(version),
        document.get("fileName") or file.get("fileName"),
    )
    task["lastDispatch"] = dispatch
    payload = {"knowledgeTaskId": task["id"], "taskType": "ocr", **dispatch}
    if storage_migration:
        payload["storageMigration"] = {
            "storageKey": storage_migration["storageKey"],
            "storageBucket": storage_migration["storageBucket"],
        }
    return payload


def dispatch_knowledge_file_index_pipeline(file: dict[str, Any], *, reason: str) -> list[dict[str, Any]]:
    # 标准库不走这条路——理由与那次数据损坏见 libs/knowledge_indexing.py
    reject_if_dedicated_ingestion(file)
    document = repo.find_one("documents", file.get("documentId"))
    version = repo.find_one("versions", file.get("documentVersionId"))
    if not document or not version:
        raise ValueError("missing_document_version")
    file_id = str(file["id"])
    reset_knowledge_file_derived_index(file_id)
    file["sliceStatus"] = "待切片"
    file["vectorStatus"] = "待向量化"
    file["chunkCount"] = 0
    file["vectorCount"] = 0
    file["updatedAt"] = server_time()
    version["sliceStatus"] = "待切片"
    version["vectorStatus"] = "待向量化"
    bump_record_revision(file)
    slice_task = repo.upsert_knowledge_task(
        task_type="slice",
        target_id=file_id,
        target_name=str(file.get("fileName") or file_id),
        document_id=document["id"],
        version_id=version["id"],
    )
    vector_task = repo.upsert_knowledge_task(
        task_type="vector",
        target_id=file_id,
        target_name=str(file.get("fileName") or file_id),
        document_id=document["id"],
        version_id=version["id"],
    )
    for task in (slice_task, vector_task):
        task["documentId"] = document["id"]
        task["documentVersionId"] = version["id"]
        task.pop("finishedAt", None)
        task.pop("errorMessage", None)
        repo.append_task_log(task, "info", reason)
    dispatch = task_dispatcher.dispatch_slice(file_id)
    slice_task["lastDispatch"] = dispatch
    return [{"knowledgeTaskId": slice_task["id"], "taskType": "slice", **dispatch}]


def missing_required_fields(item: dict[str, Any], fields: list[str]) -> list[str]:
    return [field for field in fields if item.get(field) in {None, ""}]


def resolved_role_for_read(request: Request, role: str | None = None, x_role: str | None = None) -> tuple[str, JSONResponse | None]:
    effective_role, identity_error = effective_role_for_request(request, x_role)
    if identity_error:
        return "inspection", identity_error
    requested_role = role_from_query(role, x_role)
    claims = getattr(request.state, "auth", None)
    token_role = claims.get("role") if claims else None
    if token_role and token_role != "admin":
        if requested_role != token_role:
            return requested_role, fail(errors.FORBIDDEN, request, message="请求角色与登录身份不一致。")
        return token_role, None
    return requested_role or effective_role or "inspection", None


# 这些动作一旦并发写就会无声推翻别人的结论：保存审查意见、打回补正、正式提交、
# 归档。它们必须带 If-Match（N-6），其余端点保持缺省放行，避免一次性打破所有
# 既有调用方——收紧范围可以后续按需扩大。
IF_MATCH_REQUIRED_PATH_PATTERNS = (
    re.compile(r"/inspection/nodes/[^/]+/review-opinions$"),
    re.compile(r"/inspection/nodes/[^/]+/actions/return-correction$"),
    re.compile(r"/projects/[^/]+/submissions$"),
    re.compile(r"/projects/[^/]+/reports/[^/]+/archive$"),
)


def if_match_enforced() -> bool:
    """默认开启，与认证默认值同一原则：漏配要 fail closed。

    存量调用方（尤其外部集成）迁移期间可显式设 AICHECK_REQUIRE_IF_MATCH=false
    暂时关闭；关掉后高风险写端点会退回「不发头即绕过乐观锁」的旧行为。
    """
    return os.getenv("AICHECK_REQUIRE_IF_MATCH", "true").lower() == "true"


def requires_if_match(request: Request) -> bool:
    if not if_match_enforced():
        return False
    if request.method not in {"POST", "PUT", "PATCH", "DELETE"}:
        return False
    path = canonical_path(request.url.path)
    return any(pattern.search(path) for pattern in IF_MATCH_REQUIRED_PATH_PATTERNS)


def mutation_guard(
    request: Request,
    project_id: str | None = None,
    *,
    x_role: str | None = None,
    if_match: str | None = None,
    node_ids: list[int] | None = None,
) -> JSONResponse | None:
    effective_role, identity_error = effective_role_for_request(request, x_role)
    if identity_error:
        return identity_error
    if project_id:
        project = repo.require_project(project_id)
        if not project:
            return fail(errors.NOT_FOUND, request)
        if project.get("status") == "已归档":
            return fail(errors.ARCHIVED_READONLY, request)
        effective_if_match = if_match
        if effective_if_match is None and "/reports/" not in request.url.path:
            effective_if_match = request.headers.get("If-Match")
        # N-6：不发 If-Match 就绕过乐观锁。对「一旦并发写就会推翻别人结论」的高风险
        # 动作强制要求该头——保存审查结论、打回补正、正式提交、归档。
        # 其余端点保持缺省放行，避免一次性打破所有既有调用方。
        if not effective_if_match and requires_if_match(request):
            return fail(
                errors.VALIDATION_ERROR,
                request,
                message=(
                    "该操作会改写审查结论，必须携带 If-Match 请求头（取自项目的 etag），"
                    "以免覆盖他人在此期间的修改。"
                ),
                data={"reason": "IF_MATCH_REQUIRED"},
            )
        if not project_if_match_valid(project, effective_if_match):
            return fail(errors.ETAG_CONFLICT, request)
        node_scope_error = member_node_scope_error(request, project_id, effective_role, node_ids=node_ids)
        if node_scope_error:
            return node_scope_error
    action_code = request.headers.get("X-Action-Code")
    if action_code and effective_role and action_code not in repo.role_actions(effective_role):
        return fail(errors.FORBIDDEN, request, message=f"角色 {effective_role} 无权执行 {action_code}。")
    if effective_role in FDE_ROLES:
        return fail(errors.FORBIDDEN, request, message="FDE 只能管理 AI 能力和治理流程，不能执行正式业务写操作。")
    if effective_role in {"owner"}:
        return fail(errors.FORBIDDEN, request)
    if effective_role == "admin" and "/review-opinions" in request.url.path:
        return fail(errors.FORBIDDEN, request, message="管理员不能代替业务角色保存审查意见。")
    return None


def effective_role_for_request(request: Request, x_role: str | None = None) -> tuple[str | None, JSONResponse | None]:
    header_role = x_role or request.headers.get("X-Role")
    claims = getattr(request.state, "auth", None)
    if not claims:
        return header_role, None
    token_role = claims.get("role")
    auth_user = getattr(request.state, "auth_user", None) or user_by_username(claims.get("sub"))
    token_user_id = auth_user.get("id") if auth_user else None
    header_user_id = request.headers.get("X-User-Id")
    if header_role and token_role and header_role != token_role and token_role != "admin":
        return None, fail(errors.FORBIDDEN, request, message="请求角色与登录身份不一致。")
    if header_user_id and token_user_id and header_user_id != token_user_id and token_role != "admin":
        return None, fail(errors.FORBIDDEN, request, message="请求用户与登录身份不一致。")
    return header_role or token_role, None


def request_user_id(request: Request) -> str | None:
    auth_user = getattr(request.state, "auth_user", None)
    if auth_user and auth_user.get("id"):
        return auth_user["id"]
    # S-4：X-User-Id 是客户端自称的身份，会被直接写进审计日志。认证开启时必须只认
    # 登录态——否则「谁做的」这一栏可以被任意伪造，审计链就失去意义。
    # 认证关闭是本地开发姿态，此时该头是唯一的身份来源，保留。
    if authentication_enforced():
        return None
    return request.headers.get("X-User-Id") or request.headers.get("X-Dev-User")


def request_tenant_id(request: Request) -> str:
    claims = getattr(request.state, "auth", None) or {}
    auth_user = getattr(request.state, "auth_user", None) or {}
    return str(claims.get("tid") or tenant_id_for_record(auth_user) or configured_tenant_id())


def request_actor_name(request: Request) -> str:
    user = getattr(request.state, "auth_user", None) or {}
    return str(
        user.get("displayName")
        or user.get("name")
        or user.get("username")
        or user.get("id")
        or request_user_id(request)
        or "系统"
    )


def project_role_assignee_name(project_id: str, role: str) -> str:
    member = next(
        (
            item
            for item in repo.state.get("project_members", [])
            if item.get("projectId") == project_id
            and item.get("role") == role
            and item.get("status", "启用") == "启用"
        ),
        None,
    )
    if not member:
        return "待分配"
    user = admin_user_by_id(member.get("userId")) or {}
    return str(
        member.get("name")
        or user.get("displayName")
        or user.get("name")
        or user.get("username")
        or member.get("userId")
        or "待分配"
    )


def operation_actor_key(request: Request) -> str:
    auth_user = getattr(request.state, "auth_user", None) or {}
    return str(auth_user.get("id") or auth_user.get("username") or request_user_id(request) or "anonymous")


def operation_fingerprint(value: Any) -> str:
    serialized = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str)
    return hashlib.sha256(serialized.encode("utf-8")).hexdigest()


def create_operation_preview(
    request: Request,
    *,
    kind: str,
    payload: dict[str, Any],
    base_fingerprint: str,
    impact: dict[str, Any],
) -> dict[str, Any]:
    now = datetime.now(UTC)
    preview = {
        "previewId": f"PREVIEW-{uuid4().hex[:12].upper()}",
        "kind": kind,
        "actorKey": operation_actor_key(request),
        "payloadFingerprint": operation_fingerprint(payload),
        "baseFingerprint": base_fingerprint,
        "impact": repo.clone(impact),
        "generatedAt": now.isoformat(),
        "expiresAt": (now + timedelta(minutes=OPERATION_PREVIEW_TTL_MINUTES)).isoformat(),
    }
    previews = repo.state.setdefault("operation_previews", [])
    previews.insert(0, preview)
    del previews[200:]
    return repo.clone(preview)


def validate_operation_preview(
    request: Request,
    *,
    preview_id: str | None,
    kind: str,
    payload: dict[str, Any],
    base_fingerprint: str,
) -> tuple[dict[str, Any] | None, JSONResponse | None]:
    refresh_state_from_postgres_for_live_read({"operation_previews"})
    if not preview_id:
        if strict_production():
            return None, fail(
                errors.VALIDATION_ERROR,
                request,
                message="正式环境执行该操作前必须先生成影响预览。",
            )
        return None, None
    preview = next(
        (item for item in repo.state.get("operation_previews", []) if item.get("previewId") == preview_id),
        None,
    )
    if not preview:
        return None, fail(errors.VALIDATION_ERROR, request, message="影响预览不存在，请重新预览。")
    try:
        expired = datetime.fromisoformat(str(preview.get("expiresAt"))) <= datetime.now(UTC)
    except (TypeError, ValueError):
        expired = True
    if expired:
        return None, fail(errors.CONFLICT, request, message="影响预览已过期，请重新预览。")
    if preview.get("consumedAt"):
        return None, fail(errors.CONFLICT, request, message="影响预览已使用，请重新预览。")
    if preview.get("actorKey") != operation_actor_key(request) or preview.get("kind") != kind:
        return None, fail(errors.FORBIDDEN, request, message="影响预览不属于当前用户或操作。")
    if preview.get("payloadFingerprint") != operation_fingerprint(payload):
        return None, fail(errors.CONFLICT, request, message="操作范围已变化，请重新预览。")
    if preview.get("baseFingerprint") != base_fingerprint:
        return None, fail(errors.ETAG_CONFLICT, request, message="数据版本已变化，请重新预览。")
    return preview, None


def consume_operation_preview(preview: dict[str, Any] | None) -> None:
    if preview is not None:
        preview["consumedAt"] = datetime.now(UTC).isoformat()


def member_node_scope_error(
    request: Request,
    project_id: str,
    role: str | None,
    *,
    node_ids: list[int] | None = None,
) -> JSONResponse | None:
    project = repo.require_project(project_id)
    if project and tenant_id_for_record(project) != request_tenant_id(request):
        return fail(errors.NOT_FOUND, request)
    if role == "admin":
        return None
    user_id = request_user_id(request)
    if not user_id:
        return None
    member = active_project_member_for_request(request, project_id, role)
    if member is None:
        return fail(errors.FORBIDDEN, request, message="用户未获得该项目授权。")
    requested_node_ids = {int(item) for item in node_ids or []}
    match = re.search(r"/nodes/(\d+)", request.url.path)
    if match:
        requested_node_ids.add(int(match.group(1)))
    node_scope = {int(item) for item in member.get("nodeScope") or []}
    out_of_scope = sorted(requested_node_ids - node_scope)
    if out_of_scope:
        return fail(errors.FORBIDDEN, request, message="用户不在该节点授权范围内。")
    return None


def node_ids_from_body(body: dict[str, Any], default_node_id: int | None = None) -> list[int]:
    raw_node_ids = body.get("nodeIds")
    if not raw_node_ids:
        raw_node_ids = [body.get("nodeId") or default_node_id]
    return [int(item) for item in raw_node_ids if item is not None and item != ""]


def binding_node_ids(project_id: str, binding_id: str) -> list[int]:
    binding = repo.find_one("bindings", binding_id)
    if not binding or binding.get("projectId") != project_id:
        return []
    return [int(binding["nodeId"])]


def document_node_ids(project_id: str, document_id: str) -> list[int]:
    document = repo.find_one("documents", document_id)
    if not document or document.get("projectId") != project_id:
        return []
    node_ids = {
        int(binding["nodeId"])
        for binding in repo.state["bindings"]
        if binding.get("projectId") == project_id and binding.get("documentId") == document_id
    }
    _add_node_id(node_ids, document.get("nodeId"))
    return sorted(node_ids)


def document_bindings(project_id: str, document_id: str) -> list[dict[str, Any]]:
    return [
        item
        for item in repo.state["bindings"]
        if item.get("projectId") == project_id and item.get("documentId") == document_id
    ]


def document_has_submitted_binding(project_id: str, document_id: str) -> bool:
    return any(
        binding.get("bindingStatus") in SUBMITTED_DOCUMENT_BINDING_STATUSES
        for binding in document_bindings(project_id, document_id)
    )


def document_has_project_pool_submission(project_id: str, document_id: str) -> bool:
    document = repo.find_one("documents", document_id)
    return bool(
        document
        and document.get("projectId") == project_id
        and document.get("poolSubmissionStatus") == "已提交"
    )


def document_is_locked_from_delete(project_id: str, document_id: str) -> bool:
    return document_has_project_pool_submission(project_id, document_id) or document_has_submitted_binding(
        project_id, document_id
    )


def is_project_level_submission(body: dict[str, Any]) -> bool:
    return str(body.get("submissionType") or "").strip().lower() == "project"


def project_submission_document_ids(project_id: str, body: dict[str, Any]) -> tuple[list[str], list[str]]:
    requested_ids = [str(item) for item in (body.get("documentIds") or []) if item]
    valid_ids: list[str] = []
    invalid_ids: list[str] = []
    for document_id in requested_ids:
        document = repo.find_one("documents", document_id)
        if not document or document.get("projectId") != project_id:
            invalid_ids.append(document_id)
            continue
        if document.get("fileStatus") in {"已撤回", "已作废", "已删除"}:
            invalid_ids.append(document_id)
            continue
        valid_ids.append(document_id)
    return list(dict.fromkeys(valid_ids)), list(dict.fromkeys(invalid_ids))


def document_storage_targets(document_id: str) -> set[tuple[str, str]]:
    targets: set[tuple[str, str]] = set()
    for version in repo.state.get("versions", []):
        if version.get("documentId") != document_id:
            continue
        storage_key = str(version.get("storageKey") or "")
        parsed = parse_storage_url(storage_key)
        if parsed:
            targets.add(parsed)
            continue
        storage_bucket = str(version.get("storageBucket") or "")
        if (
            storage_bucket
            and storage_key
            and not storage_key.startswith(("local://", "mock://", "http://", "https://"))
        ):
            targets.add((storage_bucket, storage_key))
    return targets


def remove_document_storage_objects(document_id: str) -> int:
    removed = 0
    for bucket, object_name in sorted(document_storage_targets(document_id)):
        if object_storage.remove_object(bucket, object_name):
            removed += 1
    return removed


