def linked_review_run(run: dict[str, Any]) -> dict[str, Any] | None:
    """AI 运行关联的 ReviewRun——真实失败原因写在它身上。"""
    review_run_id = str(run.get("reviewRunId") or "")
    if not review_run_id:
        return None
    for item in repo.state.get("review_runs") or []:
        if isinstance(item, dict) and str(item.get("reviewRunId") or "") == review_run_id:
            return item
    return None


def safe_ai_run_view(run: dict[str, Any]) -> dict[str, Any]:
    view = repo.clone(run)
    # 失败时给出可读归因与下一步。原先界面只显示「异常」两个字，errorMessage
    # 明明躺在库里却没人下发——静默的失败比响亮的失败更贵。
    #
    # 必须带上关联的 review_run：ai_run 上那条 errorMessage 是写死的模板串
    # （"Temporal/LangGraph 审查编排执行失败。"），真实异常在 review_run 的
    # errorCode/errorMessage 里。只看 ai_run 会把「资料超出模型上下文预算」
    # 误诊成「编排服务连不上」，让人去查一个好好的服务。
    failure = ai_run_failure_view(run, linked_review_run(run))
    if failure:
        view["failure"] = failure
    # 证据被裁减过就要说出来。悄悄少送几份、模型照常给结论，是这轮审计里
    # 反复出现的那类最贵的失败——看起来一切正常。
    review_run = linked_review_run(run) or {}
    # 对账：ai_run 说「推理中」而它的 ReviewRun 早已终结，就按 ReviewRun 的实况显示。
    #
    # 线上实测（2026-08-16）：节点 24 的 ReviewRun 9 秒 failed，ai_run 却一直
    # 停在「推理中」——全库 80 条里有 15 条这样，界面于是永远「执行中 3/7」，
    # 刷新也不变。写侧的漏回写已经修了（resolve_ai_run 找不到会出声），
    # 但**已经卡住的这些记录不会自己好**，读侧不兜住就还会继续骗人。
    #
    # 只改展示，不改库：库里那份是执行留痕，事后追责要看原样。
    settled = {
        "failed": "失败",
        "failed_to_start": "失败",
        "completed": "完成",
        "waiting_human_review": "待人工确认",
        "waiting_human_input": "待人工确认",
        "canceled": "已取消",
    }.get(str(review_run.get("status") or "").lower())
    if settled and str(view.get("status") or "") in {"推理中", "queued", "running", "等待重试"}:
        view["status"] = settled
        view["statusReconciledFrom"] = "reviewRun"
    budget = review_run.get("evidenceBudget")
    if isinstance(budget, dict) and budget.get("truncated"):
        view["evidenceBudget"] = repo.clone(budget)
    prompt_audit = view.get("promptAudit") if isinstance(view.get("promptAudit"), dict) else {}
    view["promptSummary"] = {
        key: prompt_audit.get(key)
        for key in (
            "promptVersion",
            "ruleVersion",
            "messagesHash",
            "promptHash",
            "responseHash",
            "payloadPolicy",
            # 本次给了模型哪些工具——裁剪会改变判定，复盘时要能看见
            "toolScope",
        )
        if prompt_audit.get(key) is not None
    }
    for field in (
        "rawPrompt",
        "rawOcrText",
        "prompt",
        "promptAudit",
        "messages",
        "llmMetadata",
        "reasoningProcess",
        "llmResultText",
        "inputPayload",
        "outputPayload",
    ):
        view.pop(field, None)
    return view


def scope_error_for_record(request: Request, record: dict[str, Any], project_id: str | None = None) -> JSONResponse | None:
    if record_visible_for_request(request, record, project_id):
        return None
    if tenant_id_for_record(record) != request_tenant_id(request):
        return fail(errors.NOT_FOUND, request)
    return fail(errors.FORBIDDEN, request, message="用户不在该资源授权范围内。")


def idempotency_fingerprint(source: Any) -> str:
    encoded = json.dumps(source, ensure_ascii=False, sort_keys=True, default=str, separators=(",", ":"))
    return hashlib.sha256(encoded.encode("utf-8")).hexdigest()


def idempotent(request: Request, key: str | None, producer, fingerprint_source: Any | None = None):
    if not key:
        return producer()
    actor_id = operation_actor_key(request)
    role = (getattr(request.state, "auth", None) or {}).get("role") or request.headers.get("X-Role") or "anonymous"
    key_hash = idempotency_fingerprint(key)
    scope = f"{request_tenant_id(request)}:{actor_id}:{role}:{request.method}:{request.url.path}:{key_hash}"
    cached = repo.state["idempotency"].get(scope)
    fingerprint = idempotency_fingerprint(fingerprint_source) if fingerprint_source is not None else None
    # 摘要只看请求所涉项目；粒度依据与旧格式升级见 idempotency_scope 模块
    authorization_digest, legacy_digest = replay_authorization_digests(
        request,
        fingerprint=idempotency_fingerprint,
        tenant_id=request_tenant_id(request),
        actor_id=actor_id,
        role=role,
        user_id=request_user_id(request),
    )
    if cached is not None:
        if isinstance(cached, dict) and "response" in cached:
            if fingerprint and cached.get("requestHash") and cached["requestHash"] != fingerprint:
                return fail(errors.IDEMPOTENCY_KEY_CONFLICT, request)
            if cached.get("authorizationDigest") != authorization_digest:
                if cached.get("authorizationDigest") != legacy_digest:
                    return fail(errors.FORBIDDEN, request, message="当前授权上下文已变化，不能重放历史响应。")
                cached["authorizationDigest"] = authorization_digest
            return repo.clone(cached["response"])
        return repo.clone(cached)
    result = producer()
    if not isinstance(result, JSONResponse):
        repo.state["idempotency"][scope] = {
            "requestHash": fingerprint,
            "authorizationDigest": authorization_digest,
            "tenantId": request_tenant_id(request),
            "actorId": actor_id,
            "actorRole": role,
            "response": repo.clone(result),
        }
    return result


def filter_keyword(items: list[dict[str, Any]], keyword: str | None, fields: list[str]) -> list[dict[str, Any]]:
    if not keyword:
        return items
    lowered = keyword.lower()
    return [
        item
        for item in items
        if any(lowered in str(item.get(field, "")).lower() for field in fields)
    ]


def admin_org_units() -> list[dict[str, Any]]:
    return repo.state["admin_config"].setdefault("orgUnits", [])


def admin_config_users() -> list[dict[str, Any]]:
    return repo.state["admin_config"].setdefault("users", [])


def demo_user_by_id(user_id: str | None) -> dict[str, Any] | None:
    if not user_id:
        return None
    return next((user for user in USERS.values() if user.get("id") == user_id), None)


def admin_user_by_id(user_id: str | None) -> dict[str, Any] | None:
    if not user_id:
        return None
    return next((user for user in repo.state.get("users", []) if user.get("id") == user_id), None)


def admin_user_projection(user: dict[str, Any]) -> dict[str, Any]:
    role = str(user.get("role") or "inspection")
    name = user.get("name") or user.get("displayName") or user.get("username") or "未命名用户"
    org_name = user.get("orgName") or user.get("orgUnitName") or ""
    org = find_org_unit(user.get("orgId"), org_name)
    canonical_org_name = (org or {}).get("name") or org_name
    projected = {
        "id": user.get("id") or f"USER-{uuid4().hex[:8].upper()}",
        "username": user.get("username") or role,
        "name": name,
        "displayName": user.get("displayName") or name,
        "orgId": user.get("orgId") or (org or {}).get("id"),
        "orgName": canonical_org_name,
        "orgUnitName": canonical_org_name,
        "role": role,
        "roleId": user.get("roleId") or role,
        "roleLabel": user.get("roleLabel") or ROLE_LABELS.get(role, role),
        "mobile": user.get("mobile") or "",
        # 界面要显示「这个人是不是本组织负责人」，不带出来的话后台没法勾选
        "isOrgLeader": bool(user.get("isOrgLeader")),
        "status": user.get("status") or "启用",
        "mustChangePassword": bool(user.get("mustChangePassword")),
        "lastLoginAt": user.get("lastLoginAt") or "",
        "updatedAt": user.get("updatedAt") or server_time(),
        "revision": record_revision(user),
    }
    if user.get("etag"):
        projected["etag"] = user["etag"]
    return projected


def upsert_admin_config_user(user: dict[str, Any]) -> None:
    projected = admin_user_projection(user)
    users = admin_config_users()
    existing = next((item for item in users if item.get("id") == projected["id"]), None)
    if existing:
        existing.update(projected)
    else:
        users.insert(0, projected)


def remove_admin_config_user(user_id: str) -> None:
    users = admin_config_users()
    users[:] = [item for item in users if item.get("id") != user_id]


def list_admin_users() -> list[dict[str, Any]]:
    merged: dict[str, dict[str, Any]] = {}
    for user in admin_config_users():
        projected = admin_user_projection(user)
        merged[projected["id"]] = projected
    for user in repo.state.get("users", []):
        projected = admin_user_projection(user)
        versioned = versioned_record("admin-user", {**user, "id": projected["id"]})
        projected["revision"] = versioned["revision"]
        projected["etag"] = versioned["etag"]
        projected["updatedAt"] = versioned["updatedAt"]
        merged[projected["id"]] = {**merged.get(projected["id"], {}), **projected}
    return list(merged.values())


def versioned_admin_user(user: dict[str, Any]) -> dict[str, Any]:
    projected = admin_user_projection(user)
    versioned = versioned_record("admin-user", {**user, "id": projected["id"]})
    projected["revision"] = versioned["revision"]
    projected["etag"] = versioned["etag"]
    projected["updatedAt"] = versioned["updatedAt"]
    return projected


def list_admin_org_units() -> list[dict[str, Any]]:
    return [versioned_record("org-unit", item) for item in admin_org_units()]


def find_org_unit(org_id: str | None = None, org_name: str | None = None) -> dict[str, Any] | None:
    if org_id:
        matches = [org for org in admin_org_units() if org.get("id") == org_id]
    elif org_name:
        normalized_name = normalized_organization_name(org_name)
        matches = [
            org
            for org in admin_org_units()
            if normalized_organization_name(org.get("name")) == normalized_name
        ]
    else:
        return None
    return matches[0] if len(matches) == 1 else None


def user_belongs_to_org(
    user: dict[str, Any],
    org: dict[str, Any] | None,
    expected_org_name: str,
) -> bool:
    user_org_id = str(user.get("orgId") or "").strip()
    org_id = str((org or {}).get("id") or "").strip()
    if user_org_id and org_id:
        return user_org_id == org_id
    return str(user.get("orgName") or "").strip() == expected_org_name.strip()


def org_type_matches_role(role: str, org_type: str | None) -> bool:
    expected_types = BUSINESS_ROLE_ORG_TYPES.get(role)
    return not expected_types or str(org_type or "") in expected_types


def validate_user_org_binding(
    request: Request,
    role: str,
    org_id: str | None,
    org_name: str | None,
) -> tuple[dict[str, Any] | None, JSONResponse | None]:
    org = find_org_unit(org_id, org_name)
    if role in BUSINESS_ROLE_ORG_TYPES and org is None:
        return None, fail(errors.VALIDATION_ERROR, request, message="监检、施工方、无损检测、建设方用户必须绑定组织。")
    if org is None:
        return None, None
    if org.get("status") == "停用":
        return None, fail(errors.CONFLICT, request, message="停用组织不能绑定用户。")
    if not org_type_matches_role(role, org.get("type")):
        return None, fail(errors.VALIDATION_ERROR, request, message="用户角色与组织类型不匹配。")
    return org, None


def role_id_for_admin_user(role: str) -> str:
    order = ["admin", "inspection", "contractor", "ndt", "owner", "fde"]
    return str(order.index(role) + 1) if role in order else role


def build_admin_user_record(
    body: dict[str, Any],
    *,
    existing: dict[str, Any] | None = None,
    org: dict[str, Any] | None = None,
) -> dict[str, Any]:
    role = str(body.get("role") or (existing or {}).get("role") or "inspection")
    username = str(body.get("username") or (existing or {}).get("username") or role).strip()
    name = str(body.get("name") or body.get("displayName") or (existing or {}).get("name") or (existing or {}).get("displayName") or username).strip()
    org_id = (org or {}).get("id") or body.get("orgId") or (existing or {}).get("orgId")
    org_name = (org or {}).get("name") or body.get("orgName") or (existing or {}).get("orgName") or (existing or {}).get("orgUnitName") or ""
    password = body.get("password") or body.get("initialPassword")
    password_hash = (existing or {}).get("passwordHash")
    if password:
        password_hash = hash_password(str(password))
    user = {
        **(existing or {}),
        "id": body.get("id") or (existing or {}).get("id") or f"USER-{uuid4().hex[:8].upper()}",
        "tenantId": tenant_id_for_record(existing) if existing else current_tenant_id(),
        "username": username,
        "name": name,
        "displayName": name,
        "passwordHash": password_hash,
        "authVersion": int((existing or {}).get("authVersion") or 0),
        "mustChangePassword": (
            True
            if password and existing is not None
            else bool((existing or {}).get("mustChangePassword"))
        ),
        "role": role,
        "roleId": role_id_for_admin_user(role),
        "roleLabel": ROLE_LABELS.get(role, role),
        "permissions": body.get("permissions") or (existing or {}).get("permissions") or repo.role_actions(role),
        "orgId": org_id,
        "orgName": org_name,
        "orgUnitName": org_name,
        "mobile": body.get("mobile") or (existing or {}).get("mobile") or "",
        # 组织负责人标记（0817 第 5 条）。**只有系统管理员能设**——
        # 让负责人自己给自己或别人加这个标记，就等于把权限下放变成了提权通道。
        # 只认显式的 True/False：不写这个字段时保持原值，别把没提到的当成取消。
        "isOrgLeader": bool(body["isOrgLeader"]) if "isOrgLeader" in body else bool((existing or {}).get("isOrgLeader")),
        "status": body.get("status") or (existing or {}).get("status") or "启用",
        "defaultPath": ROLE_DEFAULT_PATHS.get(role, ROLE_DEFAULT_PATHS["inspection"]),
        "lastLoginAt": body.get("lastLoginAt") or (existing or {}).get("lastLoginAt") or "",
        "updatedAt": server_time(),
        "revision": record_revision(existing or {"id": body.get("id") or "new"}),
    }
    if existing:
        user["revision"] = record_revision(existing)
    return user


def sync_user_references(user: dict[str, Any]) -> None:
    for member in repo.state.get("project_members", []):
        if member.get("userId") != user.get("id"):
            continue
        member["name"] = user.get("name") or user.get("displayName") or member.get("name")
        member["orgId"] = user.get("orgId")
        member["orgName"] = user.get("orgName") or member.get("orgName")
        member["role"] = user.get("role") or member.get("role")
        if user.get("status") != "启用" and member.get("status") == "启用":
            member["status"] = "停用"
        bump_record_revision(member)


def enable_admin_identity_flush(
    request: Request,
    *,
    include_users: bool = False,
    include_project_members: bool = False,
) -> None:
    state_keys = {"audit_logs"}
    if include_users:
        state_keys.add("users")
    if include_project_members:
        state_keys.add("project_members")
    request.state.flush_state_keys = state_keys
    request.state.flush_singleton_keys = {"admin_config"}


def unique_admin_value_conflict(
    user_id: str | None,
    *,
    username: str | None = None,
    mobile: str | None = None,
) -> str | None:
    for user in list_admin_users():
        if user_id and user.get("id") == user_id:
            continue
        if username and user.get("username") == username:
            return "用户名已存在，请更换用户名。"
        if mobile and user.get("mobile") and user.get("mobile") == mobile:
            return "手机号已存在，请更换手机号。"
    return None


def resolve_project_member_grant(project_id: str, role: str) -> dict[str, Any]:
    project = repo.require_project(project_id)
    role_def: dict[str, Any] | None = None
    pack: dict[str, Any] | None = None
    if project:
        try:
            pack = business_pack_for_project(project)
        except Exception:
            pack = None
    if pack:
        role_def = next((item for item in pack.get("roles") or [] if item.get("code") == role), None)
        if role_def is None:
            platform_roles = PLATFORM_ROLE_FALLBACKS.get(role) or set()
            role_def = next((item for item in pack.get("roles") or [] if item.get("platformRole") in platform_roles), None)
    node_scope = [
        int(item["nodeId"])
        for item in (pack or {}).get("nodeTemplates", [])
        if item.get("nodeId") is not None
    ]
    if not node_scope:
        node_scope = [int(ROLE_NODE_MAP.get(role, 1))]
    return {
        "role": role,
        "nodeScope": list(dict.fromkeys(node_scope)),
        "actions": list((role_def or {}).get("actions") or repo.role_actions(role)),
    }


def signed_url_for_task(task: dict[str, Any]) -> dict[str, Any] | JSONResponse:
    if task["status"] == "已过期":
        return {"error": errors.EXPORT_TASK_EXPIRED}
    if task["status"] != "可下载":
        return {"error": errors.EXPORT_TASK_NOT_READY}
    if not task.get("downloadUrl"):
        return {"error": errors.EXPORT_TASK_NOT_READY}
    return repo.signed_get(
        task["fileName"],
        task["downloadUrl"],
        content_type=task.get("contentType"),
        file_size=task.get("fileSize"),
    )


def admin_user_snapshot(user_id: str | None, role: str | None = None) -> dict[str, Any]:
    user = admin_user_by_id(user_id)
    if user is None:
        user = next((item for item in admin_config_users() if item.get("id") == user_id), None)
    if user is None and os.getenv("AICHECK_ENABLE_DEMO_DATA", "false").lower() == "true":
        demo_user = demo_user_by_id(user_id)
        if demo_user:
            user = {
                **demo_user,
                "name": demo_user.get("displayName") or demo_user.get("username"),
                "orgName": demo_user.get("orgUnitName"),
            }
    if user is None and role:
        user = next((item for item in list_admin_users() if item.get("role") == role), None)
    if user:
        projected = admin_user_projection(user)
        return {
            **projected,
            "permissions": user.get("permissions") or repo.role_actions(projected["role"]),
        }
    return {"id": user_id or "USER-UNKNOWN", "name": "待配置用户", "orgName": "", "role": role or "inspection"}


def scoped_binding_ids(project_id: str, node_ids: list[int], binding_ids: list[str] | None) -> list[str]:
    if binding_ids:
        return binding_ids
    scoped = [
        item["id"]
        for item in repo.state["bindings"]
        if item["projectId"] == project_id
        and int(item["nodeId"]) in set(node_ids)
        and item.get("bindingStatus") != "已通过"
    ]
    return scoped


def ensure_submission_document_bindings(
    project_id: str,
    node_ids: list[int],
    document_ids: list[str],
    *,
    usage: str = "原始提交",
) -> tuple[list[str], list[str], list[str]]:
    binding_ids: list[str] = []
    created_ids: list[str] = []
    invalid_ids: list[str] = []
    for raw_document_id in document_ids:
        document_id = str(raw_document_id or "").strip()
        if not document_id:
            continue
        document = repo.find_one("documents", document_id)
        if not document or document.get("projectId") != project_id:
            invalid_ids.append(document_id)
            continue
        version_id = document.get("currentVersionId")
        version = repo.find_one("versions", version_id) if version_id else None
        if not version_id:
            invalid_ids.append(document_id)
            continue
        for node_id in node_ids:
            existing = next(
                (
                    item
                    for item in repo.state["bindings"]
                    if item.get("projectId") == project_id
                    and int(item.get("nodeId") or 0) == int(node_id)
                    and item.get("documentId") == document_id
                    and item.get("documentVersionId") == version_id
                ),
                None,
            )
            if existing:
                binding_ids.append(existing["id"])
                continue
            requirements = [item for item in repo.state["requirements"] if int(item["nodeId"]) == int(node_id)]
            requirement = requirements[len(created_ids) % len(requirements)] if requirements else None
            binding = {
                "id": f"BIND-{node_id}-{uuid4().hex[:6].upper()}",
                "projectId": project_id,
                "nodeId": node_id,
                "requirementId": requirement.get("id") if requirement else None,
                "requirementName": requirement.get("name") if requirement else None,
                "documentId": document_id,
                "documentVersionId": version_id,
                "fileName": document["fileName"],
                "versionNo": (version or {}).get("versionNo") or "V1",
                "usage": usage,
                "sourceOrgName": document["sourceOrgName"],
                "bindingStatus": "草稿挂载",
                "boundByName": document.get("uploaderName") or "系统",
                "boundAt": server_time(),
                "actions": ["submission:submit"],
            }
            repo.state["bindings"].insert(0, binding)
            binding_ids.append(binding["id"])
            created_ids.append(binding["id"])
    return binding_ids, created_ids, invalid_ids


def submission_binding_ids_from_body(
    project_id: str,
    node_ids: list[int],
    body: dict[str, Any],
) -> tuple[list[str], list[str], list[str]]:
    binding_ids = scoped_binding_ids(project_id, node_ids, body.get("bindingIds") or [])
    document_ids = [str(item) for item in (body.get("documentIds") or []) if item]
    created_binding_ids: list[str] = []
    invalid_document_ids: list[str] = []
    if document_ids:
        document_binding_ids, created_binding_ids, invalid_document_ids = ensure_submission_document_bindings(
            project_id,
            node_ids,
            document_ids,
            usage=body.get("usage") or "原始提交",
        )
        binding_ids.extend(document_binding_ids)
    return list(dict.fromkeys(binding_ids)), created_binding_ids, invalid_document_ids


def build_config_diff(target: str, object_id: str, values: dict[str, Any], *, object_name: str | None = None) -> dict[str, Any]:
    changed = []
    for field, value in values.items():
        if isinstance(value, dict):
            value = ", ".join(f"{key}: {nested}" for key, nested in value.items())
        changed.append(
            {
                "field": field,
                "label": field,
                "before": None,
                "after": value,
                "severity": "info",
            }
        )
    return {
        "target": target,
        "objectId": object_id,
        "objectName": object_name or values.get("name") or values.get("scene") or target,
        "previewedAt": server_time(),
        "changed": changed,
    }


def project_member_snapshot(
    project_id: str,
    role: str,
    user_id: str | None = None,
    *,
    org_name: str | None = None,
    node_scope: list[int] | None = None,
    actions: list[str] | None = None,
) -> dict[str, Any]:
    user = admin_user_snapshot(user_id, role)
    grant = resolve_project_member_grant(project_id, role)
    return {
        "id": f"PM-{uuid4().hex[:8].upper()}",
        "projectId": project_id,
        "userId": user_id or user["id"],
        "name": user.get("name") or "",
        "orgId": user.get("orgId"),
        "orgName": org_name or user.get("orgName") or "",
        "role": role,
        "nodeScope": node_scope or grant["nodeScope"],
        "actions": actions or grant["actions"],
        "status": "启用",
        "updatedAt": server_time(),
        "revision": 1,
    }


PARTICIPANT_ROLE_FIELDS = {
    "owner": "ownerOrgName",
    "contractor": "contractorOrgName",
    "ndt": "ndtOrgName",
    "inspection": "inspectionOrgName",
}


def participant_unit_id(project_id: str, role: str) -> str:
    return f"PU-{project_id}-{role}"


def participant_role_from_id(project_id: str, participant_id: str) -> str | None:
    expected = {
        participant_unit_id(project_id, role): role
        for role in PARTICIPANT_ROLE_FIELDS
    }
    if participant_id in expected:
        return expected[participant_id]
    normalized = str(participant_id or "").strip().lower()
    return normalized if normalized in PARTICIPANT_ROLE_FIELDS else None


def project_participant_units(project: dict[str, Any], members: list[dict[str, Any]]) -> list[dict[str, Any]]:
    role_to_project_field = PARTICIPANT_ROLE_FIELDS
    detail_by_role = project.get("participantUnitDetails") if isinstance(project.get("participantUnitDetails"), dict) else {}
    rows: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    for role in ["owner", "contractor", "ndt", "inspection"]:
        scoped_members = [member for member in members if member.get("role") == role and member.get("status") != "停用"]
        for member in scoped_members:
            org_name = project.get(role_to_project_field[role]) or member.get("orgName")
            if not org_name:
                continue
            key = (role, org_name)
            if key in seen:
                continue
            seen.add(key)
            org = find_org_unit(member.get("orgId"), org_name)
            detail = detail_by_role.get(role) if isinstance(detail_by_role.get(role), dict) else {}
            rows.append(
                {
                    "id": participant_unit_id(str(project.get("id") or ""), role),
                    "unitType": role,
                    "unitName": org_name,
                    "orgId": detail.get("orgId") or member.get("orgId") or (org or {}).get("id"),
                    "contactName": detail.get("contactName") or (org or {}).get("contactName") or member.get("name") or "",
                    "contactPhone": detail.get("contactPhone") or (org or {}).get("contactPhone") or "",
                    "memberCount": len([item for item in scoped_members if (item.get("orgName") or org_name) == org_name]),
                }
            )
        if not any(row["unitType"] == role for row in rows):
            org_name = project.get(role_to_project_field[role])
            if org_name:
                org = find_org_unit(org_name=org_name)
                detail = detail_by_role.get(role) if isinstance(detail_by_role.get(role), dict) else {}
                rows.append(
                    {
                        "id": participant_unit_id(str(project.get("id") or ""), role),
                        "unitType": role,
                        "unitName": org_name,
                        "orgId": detail.get("orgId") or (org or {}).get("id"),
                        "contactName": detail.get("contactName") or (org or {}).get("contactName") or "",
                        "contactPhone": detail.get("contactPhone") or (org or {}).get("contactPhone") or "",
                        "memberCount": 0,
                    }
                )
    return rows


def project_detail_payload(project_id: str, request: Request | None = None) -> dict[str, Any] | None:
    project = repo.require_project(project_id)
    if not project:
        return None
    members = [versioned_record("project-member", item) for item in repo.state["project_members"] if item["projectId"] == project_id]
    if request is not None and getattr(request.state, "auth", None) and getattr(request.state, "auth", {}).get("role") != "admin":
        current_user_id = request_user_id(request)
        members = [item for item in members if item.get("userId") == current_user_id]
    scope = authorized_node_scope(request, project_id) if request is not None else None
    node_summary = []
    groups = filter_node_groups_for_scope(repo.node_groups(project_id), scope)
    for group in groups:
        nodes = group["nodes"]
        node_summary.append(
            {
                "groupName": group["groupName"],
                "total": len(nodes),
                "passed": len([item for item in nodes if item.get("status") == "已通过"]),
                "pending": len([item for item in nodes if item.get("status") in {"待提交", "待审查", "待人工确认"}]),
                "correction": len([item for item in nodes if item.get("status") in {"需补正", "补正中"}]),
            }
        )
    return {
        "project": versioned_project(project),
        "members": members,
        "participantUnits": project_participant_units(project, members),
        "nodeSummary": node_summary,
        "recentExportTasks": [repo.clone(item) for item in repo.state["export_tasks"] if item.get("projectId") == project_id],
    }


def business_pack_for_project(project: dict[str, Any] | None) -> dict[str, Any]:
    pack_id = (project or {}).get("businessPackId") or DEFAULT_BUSINESS_PACK_ID
    return load_business_pack(pack_id)


def business_pack_snapshot_for_project(project: dict[str, Any]) -> dict[str, Any]:
    stored = project.get("businessPackSnapshot")
    if isinstance(stored, dict):
        return repo.clone(stored)
    return business_pack_snapshot(business_pack_for_project(project))


def business_rule_for_node(project: dict[str, Any] | None, node_id: int) -> dict[str, Any] | None:
    pack = business_pack_for_project(project)
    for rule in pack.get("ruleSets") or []:
        if int(node_id) in {int(item) for item in rule.get("nodeIds") or []}:
            return repo.clone(rule)
    return None


def knowledge_file_for_standard_reference(reference: dict[str, Any]) -> dict[str, Any] | None:
    referenced_file_id = str(reference.get("knowledgeFileId") or reference.get("fileId") or "").strip()
    if referenced_file_id:
        matched_by_id = repo.find_one("knowledge_files", resolve_knowledge_file_id(referenced_file_id))
        if matched_by_id and not knowledge_file_is_business_rule(matched_by_id):
            return matched_by_id
    raw_path = str(reference.get("file") or reference.get("sourceRelativePath") or "").strip()
    raw_name = str(reference.get("fileName") or "").strip()
    normalized_path = raw_path.replace("\\", "/").lstrip("./")
    file_name = Path(normalized_path).name if normalized_path else raw_name
    standard_files = [
        item
        for item in repo.state.get("knowledge_files", [])
        if not knowledge_file_is_business_rule(item)
    ]
    if normalized_path:
        exact = next(
            (
                item
                for item in standard_files
                if str(item.get("sourceRelativePath") or "").replace("\\", "/").lstrip("./")
                == normalized_path
            ),
            None,
        )
        if exact:
            return exact
    if not file_name:
        return None
    matches = [
        item
        for item in standard_files
        if file_name
        in {
            str(item.get("fileName") or "").strip(),
            str(item.get("originalFileName") or "").strip(),
            Path(str(item.get("sourceRelativePath") or "")).name,
        }
    ]
    return matches[0] if len(matches) == 1 else None


def enrich_standard_reference(reference: dict[str, Any]) -> dict[str, Any]:
    enriched = repo.clone(reference)
    knowledge_file = knowledge_file_for_standard_reference(enriched)
    source_path = str(
        enriched.get("sourceRelativePath")
        or enriched.get("file")
        or (knowledge_file or {}).get("sourceRelativePath")
        or ""
    ).strip()
    if source_path:
        enriched["sourceRelativePath"] = source_path
    file_id = str(enriched.get("knowledgeFileId") or (knowledge_file or {}).get("id") or "")
    page_no = enriched.get("sourcePage") or enriched.get("startPage") or enriched.get("pageNo")
    if not knowledge_file:
        enriched["previewAvailable"] = bool(file_id)
        if file_id:
            preview_url = f"/api/knowledge/files/{quote(file_id, safe='')}/original?disposition=inline"
            if page_no:
                preview_url = f"{preview_url}#page={int(page_no)}"
            enriched["previewUrl"] = preview_url
        return enriched
    preview_url = f"/api/knowledge/files/{quote(file_id, safe='')}/original?disposition=inline"
    if page_no:
        preview_url = f"{preview_url}#page={int(page_no)}"
    enriched.update(
        {
            "knowledgeFileId": file_id,
            "documentVersionId": enriched.get("documentVersionId") or knowledge_file.get("documentVersionId"),
            "fileName": enriched.get("fileName") or knowledge_file.get("fileName"),
            "sourceRelativePath": knowledge_file.get("sourceRelativePath") or source_path,
            "previewAvailable": bool(file_id and knowledge_file.get("documentId")),
            "previewUrl": preview_url,
        }
    )
    return enriched


def fixed_standard_references_for_node(project: dict[str, Any] | None, node_id: int) -> list[dict[str, Any]]:
    project_id = str((project or {}).get("id") or "")
    snapshot = clause_package_snapshot_for_project_node(repo.state, project_id, node_id)
    if not snapshot:
        return []
    standard_catalog = {
        str(item.get("id") or ""): item
        for item in business_pack_for_project(project).get("standardCatalog") or []
        if isinstance(item, dict) and item.get("id")
    }
    references: list[dict[str, Any]] = []
    for reference in snapshot.get("clauses") or []:
        role = str(reference.get("referenceRole") or "professional")
        purpose = str(reference.get("purpose") or ("直接监检依据" if role == "primary" else "专业执行条款"))
        source_file = str(reference.get("sourceFile") or "")
        catalog_item = standard_catalog.get(str(reference.get("standardRef") or ""), {})
        references.append(
            enrich_standard_reference(
                {
                    "clauseId": reference.get("sourceLocatorId"),
                    "standardRef": reference.get("standardRef"),
                    "standardCode": catalog_item.get("code"),
                    "standardName": reference.get("standardName") or catalog_item.get("name"),
                    "clauseNo": reference.get("clauseNo"),
                    "title": "直接监检依据" if role == "primary" else purpose,
                    "summary": purpose,
                    "effectiveVersion": reference.get("documentVersionId"),
                    "referenceRole": role,
                    "fixedBinding": True,
                    "verificationStatus": reference.get("verificationStatus"),
                    "packageId": snapshot.get("packageId"),
                    "packageSnapshotHash": snapshot.get("snapshotHash"),
                    "knowledgeFileId": reference.get("knowledgeFileId"),
                    "documentVersionId": reference.get("documentVersionId"),
                    "sourceRelativePath": source_file,
                    "fileName": Path(source_file).name,
                    "sourcePage": reference.get("sourcePage"),
                    "startPage": reference.get("startPage"),
                    "endPage": reference.get("endPage"),
                    "sourceLocatorId": reference.get("sourceLocatorId"),
                    "locatorPrecision": reference.get("locatorPrecision"),
                    "locators": repo.clone(reference.get("locators") or []),
                }
            )
        )
    return references


def business_pack_tool_catalog(project: dict[str, Any] | None) -> list[dict[str, Any]]:
    """业务包里的工具目录：{id, name, capability}。

    界面上把 T01/T07 这类编号翻译成业务语言需要它（X-4）。runtimeTool 是实现细节，
    不下发——业务用户不需要知道底层函数名。
    """
    pack = business_pack_for_project(project)
    catalog: list[dict[str, Any]] = []
    for item in pack.get("toolCatalog") or []:
        if not isinstance(item, dict) or not item.get("id"):
            continue
        catalog.append(
            {
                "id": str(item.get("id")),
                "name": str(item.get("name") or ""),
                "capability": str(item.get("capability") or ""),
            }
        )
    return catalog


def node_business_basis(project: dict[str, Any] | None, node_id: int) -> dict[str, Any] | None:
    rule = business_rule_for_node(project, node_id)
    if not rule:
        return None
    ai_execution = rule.get("aiExecution") if isinstance(rule.get("aiExecution"), dict) else {}
    return {
        "ruleId": rule.get("sourceRuleId") or rule.get("id") or "",
        "ruleName": rule.get("name") or rule.get("inspectionItem") or "",
        "ruleKey": rule.get("ruleKey"),
        "ruleVersion": rule.get("version"),
        "sourceDocument": rule.get("sourceDocument"),
        "sourceSequence": rule.get("sourceSequence"),
        "businessModule": rule.get("businessModule"),
        "inspectionCategory": rule.get("inspectionCategory"),
        "inspectionItem": rule.get("inspectionItem"),
        "inspectionClass": rule.get("inspectionClass") or rule.get("reviewClass"),
        "reviewClass": rule.get("reviewClass"),
        "criteria": rule.get("criteria") or rule.get("standardText") or "",
        "checkMethod": rule.get("checkMethod") or "",
        "witnessText": rule.get("witnessText") or "",
        "materialTypeCodes": repo.clone(rule.get("materialTypeCodes") or []),
        "toolIds": repo.clone(rule.get("toolIds") or []),
        # X-4：界面上原先只显示 T01/T07 这样的裸编号，监检人员无从判断它是什么。
        # 业务包的 toolCatalog 里有权威名称与能力描述，一并下发，让前端能显示
        # 「查焊工持证范围」而不是「T07」。
        "toolCatalog": business_pack_tool_catalog(project),
        # 去重在源头做。实测（2026-08-16，NDT 节点 40）：发来 69 条，
        # 去重后只有 23 条——**46 条是重复的**，每条 451 字节，白传约 20 KB。
        # 前端只好自己去重（Workbench.vue nodeReferencedStandards 里那段 seen/Set）。
        # 让每个调用方各去一遍，是把同一件事做 N 遍，还容易有人漏做。
        "referencedStandards": dedupe_standard_references(
            rule.get("referencedStandards") or []
        ),
        "aiExecution": {
            "schemaVersion": ai_execution.get("schemaVersion"),
            "sourceFields": repo.clone(ai_execution.get("sourceFields") or {}),
            "requiredEvidence": repo.clone(ai_execution.get("requiredEvidence") or []),
            "extractionTargets": repo.clone(ai_execution.get("extractionTargets") or []),
            "verificationSteps": repo.clone(ai_execution.get("verificationSteps") or []),
            "acceptanceCriteria": repo.clone(ai_execution.get("acceptanceCriteria") or []),
            "humanConfirmation": repo.clone(ai_execution.get("humanConfirmation") or []),
            "promptContext": ai_execution.get("promptContext") or "",
        },
    }


def dedupe_standard_references(items: list[Any]) -> list[dict[str, Any]]:
    """同一份标准只发一次，保持原有顺序。

    去重键与前端一致：sourceRelativePath → file → fileName → reference。
    键取不到的条目原样保留——**宁可多发一条，也不要因为字段缺失把一条
    真实引用悄悄丢掉**：审查依据少一条，比多一条重复危险得多。
    """
    seen: set[str] = set()
    result: list[dict[str, Any]] = []
    for item in items:
        if not isinstance(item, dict):
            continue
        enriched = enrich_standard_reference(item)
        key = str(
            enriched.get("sourceRelativePath")
            or enriched.get("file")
            or enriched.get("fileName")
            or enriched.get("reference")
            or ""
        ).strip()
        if key:
            if key in seen:
                continue
            seen.add(key)
        result.append(enriched)
    return result


def project_pack_member_roles(pack: dict[str, Any]) -> list[dict[str, Any]]:
    assignments: list[dict[str, Any]] = []
    seen: set[str] = set()
    for role in pack.get("roles") or []:
        code = str(role.get("code") or "").strip()
        if not code or code == "admin":
            continue
        user_role = code if code in BUSINESS_ROLE_ORG_TYPES else PACK_PLATFORM_USER_ROLES.get(str(role.get("platformRole") or ""))
        if not user_role or user_role in seen:
            continue
        seen.add(user_role)
        assignments.append({**role, "userRole": user_role})
    return assignments


def exact_admin_user(user_id: str | None) -> dict[str, Any] | None:
    if not user_id:
        return None
    user = admin_user_by_id(user_id) or next(
        (item for item in admin_config_users() if item.get("id") == user_id),
        None,
    )
    if user is None and os.getenv("AICHECK_ENABLE_DEMO_DATA", "false").lower() == "true":
        user = demo_user_by_id(user_id)
    return admin_user_projection(user) if user else None


def review_point_requirement(point: dict[str, Any]) -> dict[str, Any]:
    return {
        "id": point.get("id"),
        "projectId": None,
        "nodeId": int(point.get("nodeId") or 0),
        "name": point.get("reviewContent") or point.get("materialTypeName") or "业务资料审查点",
        "requiredType": point.get("requiredType") or "条件必传",
        "materialTypeCode": point.get("materialTypeCode"),
        "materialTypeName": point.get("materialTypeName"),
        "materialCategory": point.get("materialCategory"),
        "responsibleParty": point.get("responsibleParty"),
        "evidenceItems": repo.clone(point.get("evidenceItems") or []),
        "note": point.get("fileContent") or point.get("mappingRelation"),
        "source": "materialReviewPoint",
    }


def project_requirements_for_node(project_id: str, node_id: int) -> list[dict[str, Any]]:
    project = repo.require_project(project_id)
    review_points = review_points_for_project(repo, project, node_id=node_id)
    if review_points:
        return [review_point_requirement(point) for point in review_points]
    scoped = [
        repo.clone(item)
        for item in repo.state["requirements"]
        if int(item["nodeId"]) == int(node_id) and item.get("projectId") == project_id
    ]
    if scoped:
        return scoped
    return [
        repo.clone(item)
        for item in repo.state["requirements"]
        if int(item["nodeId"]) == int(node_id) and not item.get("projectId")
    ]
    try:
        pack = business_pack_for_project(project)
    except Exception:
        return []
    return [
        repo.clone(item)
        for item in build_project_requirements(pack, project_id=project_id)
        if int(item["nodeId"]) == int(node_id)
    ]


def requirement_matches_binding(requirement: dict[str, Any], binding: dict[str, Any]) -> bool:
    requirement_id = str(requirement.get("id") or "").strip()
    binding_requirement_id = str(binding.get("requirementId") or "").strip()
    if requirement_id and binding_requirement_id and requirement_id == binding_requirement_id:
        return True
    binding_review_point_ids = {str(item).strip() for item in binding.get("reviewPointIds") or [] if str(item).strip()}
    if requirement_id and requirement_id in binding_review_point_ids:
        return True
    requirement_name = str(requirement.get("name") or "").strip()
    binding_requirement_name = str(binding.get("requirementName") or "").strip()
    return bool(requirement_name and binding_requirement_name and requirement_name == binding_requirement_name)


def build_node_requirements_summary(
    project_id: str,
    node: dict[str, Any],
    *,
    node_bindings: list[dict[str, Any]] | None = None,
    evidence_readiness: dict[str, Any] | None = None,
) -> dict[str, Any]:
    evidence_readiness = evidence_readiness or build_node_evidence_readiness(repo, project_id, int(node["nodeId"]))
    if evidence_readiness.get("hasReviewPoints"):
        return {
            "requiredCount": evidence_readiness["requiredCount"],
            "satisfiedCount": evidence_readiness["satisfiedCount"],
            "missingCount": evidence_readiness["missingCount"],
            "progressPercent": evidence_readiness["progressPercent"],
            "hasRequirementDetails": True,
            "source": "nodeEvidenceLinks",
            "readyForAi": evidence_readiness["readyForAi"],
            "supportingDocumentCount": evidence_readiness["supportingDocumentCount"],
            "requirements": evidence_readiness["requirements"],
            "missingRequirements": evidence_readiness["missingRequirements"],
        }
    requirements = project_requirements_for_node(project_id, int(node["nodeId"]))
    bindings = node_bindings if node_bindings is not None else repo.bindings_for_node(project_id, int(node["nodeId"]))
    matched_requirements: list[dict[str, Any]] = []
    missing_requirements: list[dict[str, Any]] = []
    active_required_count = 0
    satisfied_count = 0

    for requirement in requirements:
        matches = [binding for binding in bindings if requirement_matches_binding(requirement, binding)]
        matched = {
            **repo.clone(requirement),
            "matchedBindingCount": len(matches),
            "matchedFileNames": sorted({str(binding.get("fileName") or "") for binding in matches if binding.get("fileName")}),
            "fulfilled": bool(matches),
        }
        matched_requirements.append(matched)
        if requirement.get("requiredType") != "可选":
            active_required_count += 1
            if matched["fulfilled"]:
                satisfied_count += 1
            else:
                missing_requirements.append(matched)

    has_requirement_details = bool(requirements)
    if not has_requirement_details:
        progress = node.get("requiredProgress") or {}
        active_required_count = int(progress.get("total") or 0)
        satisfied_count = min(active_required_count, int(progress.get("done") or 0))
        missing_count = max(active_required_count - satisfied_count, 0)
        if missing_count:
            missing_requirements.append(
                {
                    "id": f"REQ-{node['nodeId']}-UNSPECIFIED",
                    "projectId": project_id,
                    "nodeId": int(node["nodeId"]),
                    "name": "资料要求明细未配置",
                    "requiredType": "必传",
                    "materialTypeCode": None,
                    "note": "当前节点仅返回进度摘要，未返回具体资料要求名称。",
                    "matchedBindingCount": 0,
                    "matchedFileNames": [],
                    "fulfilled": False,
                }
            )
    else:
        missing_count = len(missing_requirements)

    progress_percent = round((satisfied_count / active_required_count) * 100) if active_required_count else 0
    return {
        "requiredCount": active_required_count,
        "satisfiedCount": satisfied_count,
        "missingCount": missing_count,
        "progressPercent": progress_percent,
        "hasRequirementDetails": has_requirement_details,
        "requirements": matched_requirements,
        "missingRequirements": missing_requirements,
    }


def _requirement_display_name(item: dict[str, Any]) -> str:
    """需求项对人显示的名字。

    与前端 requirementDisplayName 同一套优先级——两处写不一致时，
    同一条资料在列表和详情里会显示成两个名字，那比没有名字更让人怀疑数据。
    """
    for key in ("materialTypeName", "reviewContent", "name", "materialTypeCode"):
        value = str(item.get(key) or "").strip()
        if value:
            return value
    return "未命名资料"


def slim_requirements_summary(summary: dict[str, Any]) -> dict[str, Any]:
    """树视图用的瘦身版摘要：只留计数和缺失项名称。

    实测（2026-08-16，建设方首屏）：/tree 返回 382 KB，其中
    requirementsSummary 一个字段占 349 KB——**91%**。69 个节点，
    每个都拖着 requirements 和 missingRequirements 两份完整明细
    （两个数组长度一模一样，同一批需求装了两遍），每项还带着
    source 文档路径、revision、updatedAt、minConfidence、evidenceItems……

    而树上只用到四个计数和缺失项的 name（见 Workbench.vue
    inspectionProjectNodeRows）。明细在 /nodes/{id}/package 里另发一份，
    点开哪个节点才取哪个——**列表页不该替详情页把数据先背一遍**。
    """
    return {
        "requiredCount": summary.get("requiredCount", 0),
        "satisfiedCount": summary.get("satisfiedCount", 0),
        "missingCount": summary.get("missingCount", 0),
        "progressPercent": summary.get("progressPercent", 0),
        "hasRequirementDetails": summary.get("hasRequirementDetails", False),
        "supportingDocumentCount": summary.get("supportingDocumentCount", 0),
        # 树上只显示名字。带 id 是为了点进去能对上，不是为了展示。
        #
        # 名称的取法要和前端 requirementDisplayName 一致：
        # materialTypeName → reviewContent → name → materialTypeCode。
        # **真实需求项根本没有 name 字段**——名称在 materialTypeName 里，
        # 只有「明细未配置」那个占位分支才写 name。所以前端那句
        # `.map(r => r.name)` 一直取到 undefined，缺失资料名这一列本来就是空的，
        # 只是没人注意；我做瘦身时才把它暴露出来。
        # materialTypeCode 要留：它是这条需求的**身份**，不是明细。
        # 瘦身那次把它一起砍了（76fbcf2），于是调用方只能靠显示名去对，
        # 而显示名会随配置改动——test_business_pack 立刻红了，我当时
        # 误判成「既有失败、与我无关」。砍大字段没错，砍身份是错的。
        "missingRequirements": [
            {"id": item.get("id"), "materialTypeCode": item.get("materialTypeCode"), "name": _requirement_display_name(item)}
            for item in (summary.get("missingRequirements") or [])
            if isinstance(item, dict)
        ],
    }


def enrich_node_with_requirements_summary(
    project_id: str,
    node: dict[str, Any],
    *,
    project_bindings: list[dict[str, Any]] | None = None,
    evidence_readiness: dict[str, Any] | None = None,
    slim: bool = False,
) -> dict[str, Any]:
    enriched = repo.clone(node)
    node_bindings = [
        binding
        for binding in (project_bindings if project_bindings is not None else repo.bindings_for_node(project_id, int(node["nodeId"])))
        if int(binding.get("nodeId") or 0) == int(node["nodeId"])
    ]
    summary = build_node_requirements_summary(project_id, enriched, node_bindings=node_bindings, evidence_readiness=evidence_readiness)
    enriched["requirementsSummary"] = slim_requirements_summary(summary) if slim else summary
    enriched["fileCount"] = len(node_bindings)
    if summary["hasRequirementDetails"]:
        enriched["requiredProgress"] = {
            "done": summary["satisfiedCount"],
            "total": summary["requiredCount"],
        }
    return enriched


def attach_business_pack_project_scaffold(project: dict[str, Any], pack: dict[str, Any]) -> tuple[int, int]:
    project_id = project["id"]
    existing_nodes = {item["id"] for item in repo.state["tree_nodes"]}
    nodes = [
        item
        for item in build_project_tree(project_id, pack)
        if item["id"] not in existing_nodes
    ]
    repo.state["tree_nodes"].extend(nodes)
    existing_requirement_keys = {
        (item.get("projectId"), item["id"]) for item in repo.state["requirements"]
    }
    requirements = [
        item
        for item in build_project_requirements(pack, project_id=project_id)
        if (item.get("projectId"), item["id"]) not in existing_requirement_keys
    ]
    repo.state["requirements"].extend(requirements)
    bind_project_node_clause_packages(
        repo.state,
        project,
        pack,
        bound_at=project.get("updatedAt") or server_time(),
    )
    return len(nodes), len(requirements)


