@router.get("/projects/{project_id}/nodes/{node_id}/package")
def node_package(request: Request, project_id: str, node_id: int):
    effective_project_id = project_id
    project = repo.require_project(effective_project_id)
    node = repo.node(effective_project_id, node_id)
    if not node:
        return fail(errors.NOT_FOUND, request)
    scope = authorized_node_scope(request, project_id)
    effective_role, identity_error = effective_role_for_request(request)
    if identity_error:
        return identity_error
    observer_view = str(effective_role or "") in REVIEW_PROCESS_OBSERVER_ROLES
    # 审查过程（AI 判定 / 人工结论）对建设方与施工方都不开放（M-9 / O-1）；
    # 整改往返与草稿可见性只挡建设方——打回理由要给施工方看，草稿本就是它自己的。
    review_process_hidden = str(effective_role or "") in REVIEW_PROCESS_RESTRICTED_ROLES
    document_repo = repo.project_document_read_view(effective_project_id)
    bindings = document_repo.bindings_for_node(effective_project_id, node_id)
    project_bindings = [
        binding
        for binding in document_repo.bindings_for_project(effective_project_id)
        if record_visible_for_scope(binding, scope, project_id=effective_project_id)
    ]
    project_files = [
        attach_document_ocr_readiness(document_repo, item)
        for item in visible_project_documents_for_request(
            request,
            effective_project_id,
            document_repo=document_repo,
        )
    ]
    visible_document_ids = {str(item.get("id") or "") for item in project_files}
    bindings = [
        item for item in bindings if document_access_policy.binding_relation_visible_for_request(_DOCUMENT_ACCESS_SERVICES, request, effective_project_id, item, document_repo=document_repo)
    ]
    project_bindings = [
        item
        for item in project_bindings
        if document_access_policy.binding_relation_visible_for_request(_DOCUMENT_ACCESS_SERVICES, request, effective_project_id, item, document_repo=document_repo)
    ]
    if effective_role == "inspection":
        submitted_rows = build_inspection_submitted_document_rows(effective_project_id, scope)
        submitted_document_ids = {str(item.get("documentId") or "") for item in submitted_rows}
        submitted_binding_ids = {
            str(binding.get("id") or "")
            for item in submitted_rows
            for binding in item.get("submittedBindings") or []
        }
        # 0817 第 8 条：施工方一上传监检就能看见，不再按已提交过滤掉；
        # 但每条要标出有没有正式提交——去掉门，不是去掉区分。
        # 口径统一用 SUBMITTED_DOCUMENT_BINDING_STATUSES（不用「有没有提交记录」，
        # 两者实测不等价）。理由详见 tests/test_inspection_sees_unsubmitted.py。
        _submitted = lambda item: str(item.get("bindingStatus") or "") in SUBMITTED_DOCUMENT_BINDING_STATUSES  # noqa: E731
        submitted_doc_ids = submitted_document_ids | {
            str(item.get("documentId") or "") for item in project_bindings if _submitted(item)
        }
        bindings = [{**item, "submittedToInspection": _submitted(item)} for item in bindings]
        project_bindings = [{**item, "submittedToInspection": _submitted(item)} for item in project_bindings]
        project_files = [{**item, "submittedToInspection": str(item.get("id") or "") in submitted_doc_ids} for item in project_files]
    elif observer_view:
        # M-11：建设方原先看到的比监检还多，含施工方尚未提交的草稿挂载。
        # 与监检同一口径——只有进入审查视野的资料才对出资方可见。
        bindings = [
            item
            for item in bindings
            if str(item.get("bindingStatus") or "") in SUBMITTED_DOCUMENT_BINDING_STATUSES
        ]
        project_bindings = [
            item
            for item in project_bindings
            if str(item.get("bindingStatus") or "") in SUBMITTED_DOCUMENT_BINDING_STATUSES
        ]
        project_files = [
            item for item in project_files if document_readable_for_role(item, effective_role)
        ]
    version_ids = {item["documentVersionId"] for item in bindings}
    # 标出文件本体是否真的上传成功，供前端在提交前拦截空壳资料（同 DOCUMENT_BODY_MISSING 口径）。
    for binding in (*bindings, *project_bindings):
        binding["bodyUploaded"] = document_body_uploaded(
            repo.find_one("documents", binding.get("documentId")),
            repo.find_one("versions", binding.get("documentVersionId")),
        )
    for file in project_files:
        file_bindings = [binding for binding in project_bindings if binding.get("documentId") == file.get("id")]
        file["bindings"] = file_bindings
        file["primaryBinding"] = file_bindings[0] if file_bindings else None
        # 台账行同样要带本体标记：没有它，从未上传成功的文件会一直显示「上传中」，
        # 施工方看不出该重传，只有点了提交才会撞到 DOCUMENT_BODY_MISSING。
        file["bodyUploaded"] = document_body_uploaded(
            repo.find_one("documents", file.get("id")) or file
        )
    visible_document_ids = {item["id"] for item in project_files}
    node_ai_runs = [
        item
        for item in repo.state["ai_runs"]
        if item["projectId"] == effective_project_id and int(item["nodeId"]) == int(node_id)
    ]
    # 人工结论。既给 reviewOpinions，也给自动审核状态当输入——
    # 两处各查一遍的话，界面上「有人工结论」和「状态按人工算」会不同步。
    node_review_opinions = [] if review_process_hidden else [repo.clone(item) for item in repo.state["review_opinions"] if item["projectId"] == effective_project_id and int(item["nodeId"]) == int(node_id)]
    node_rectifications = [] if observer_view else [repo.clone(item) for item in repo.state["rectifications"] if item["projectId"] == effective_project_id and int(item["nodeId"]) == int(node_id) and document_access_policy.rectification_visible_for_request(_DOCUMENT_ACCESS_SERVICES, request, effective_project_id, item)]
    evidence_readiness = actor_node_evidence_readiness(
        request,
        effective_project_id,
        node_id,
        document_repo=document_repo,
    )
    return ok(
        {
            "node": enrich_node_with_requirements_summary(
                effective_project_id,
                node,
                project_bindings=project_bindings,
                evidence_readiness=evidence_readiness,
            ),
            "businessBasis": node_business_basis(project, node_id),
            "requirements": project_requirements_for_node(project_id, node_id),
            "evidenceReadiness": evidence_readiness,
            "nodeEvidenceLinks": evidence_readiness.get("nodeEvidenceLinks", []),
            "bindings": bindings,
            "projectFiles": project_files,
            "availableVersions": [
                document_repo.clone(item)
                for item in document_repo.state["versions"]
                if item["id"] in version_ids or item.get("documentId") in visible_document_ids
            ],
            "extractedFields": document_repo.fields_for_versions(version_ids),
            # 与独立端点同口径，否则堵了端点、节点包照漏（M-9 修复时踩过这个坑）。
            "reviewOpinions": node_review_opinions,
            # 自动审核状态（0817 第 3 条）。口径只有一份：libs/auto_review_status
            "autoReviewStatus": None if review_process_hidden else auto_review_status(node_ai_runs[0] if node_ai_runs else None, node_review_opinions[0] if node_review_opinions else None),
            # AI 回复和人工回复排在同一条线上——分在两个列表里的话，
            # 监检要自己按时间对一遍，而人一旦要自己对时间就一定会对错
            "reviewTimeline": node_review_timeline([] if review_process_hidden else node_ai_runs, node_review_opinions, node_rectifications),
            "rectifications": node_rectifications,
            # 只带最近几次运行：工作台展示的是当前状态与最近一次结果，而全量历史会让
            # 本响应膨胀到数百 KB（实测 9 次运行即 665KB），且轮询会反复重取。
            # 需要完整历史时用 /inspection/nodes/{id}/ai-runs。
            "aiRuns": (
                []
                if review_process_hidden
                else [safe_ai_run_view(item) for item in node_ai_runs[:NODE_PACKAGE_AI_RUN_LIMIT]]
            ),
            "aiRunTotal": 0 if review_process_hidden else len(node_ai_runs),
            "actions": repo.clone(node.get("actions", [])),
        },
        request,
    )


@router.get("/projects/{project_id}/documents")
def list_documents(request: Request, project_id: str, page_no: int = Query(default=1, alias="page"), page_size: int = Query(default=20, alias="pageSize"), keyword: str | None = None, nodeId: int | None = None):
    _, identity_error = effective_role_for_request(request)
    if identity_error:
        return identity_error
    effective_project_id = project_id
    document_repo = repo.project_document_read_view(effective_project_id)
    items = [
        attach_document_ocr_readiness(document_repo, item)
        for item in visible_project_documents_for_request(
            request,
            effective_project_id,
            document_repo=document_repo,
        )
    ]
    if nodeId:
        document_ids = {
            binding["documentId"]
            for binding in document_repo.state["bindings"]
            if binding.get("projectId") == effective_project_id and int(binding.get("nodeId")) == int(nodeId)
        }
        items = [item for item in items if item["id"] in document_ids]
    items = filter_keyword(items, keyword, ["fileName", "sourceOrgName", "materialCategory"])
    # M-4：只创建会话、从不 PUT 内容的空壳记录会照常出现在资料台账里，
    # 与真实资料在列表中无可视区分。带上本体标记，让台账一眼能看出哪些是空壳。
    for item in items:
        item["bodyUploaded"] = document_body_uploaded(item)
    return ok(page(items, page_no, page_size), request)


