@router.post("/projects/{project_id}/documents/upload-session/{session_id}/complete")
def complete_upload_session(
    request: Request,
    project_id: str,
    session_id: str,
    body: dict[str, Any] = Body(default_factory=dict),
    x_role: str | None = Header(default=None, alias="X-Role"),
    idempotency_key: str | None = Header(default=None, alias="Idempotency-Key"),
):
    def produce():
        guard = mutation_guard(request, project_id, x_role=x_role)
        if guard:
            return guard
        session = repo.find_one("upload_sessions", session_id)
        completion_error = upload_session_completion_error(request, project_id, session)
        if completion_error:
            return completion_error
        stored_completion = (session or {}).get("completionResult")
        if (session or {}).get("status") == "已完成" and isinstance(
            stored_completion, dict
        ):
            outcome = {**repo.clone(stored_completion), "replayed": True}
        else:
            outcome = complete_upload_session_aggregate_transaction(
                project_id, session_id, body
            )
        error_response = upload_session_transaction_error_response(request, outcome)
        if error_response:
            return error_response
        return upload_session_workflow.completed_upload_response(
            _UPLOAD_SESSION_SERVICES,
            request,
            project_id=project_id,
            session_id=session_id,
            outcome=outcome,
            dispatch_files=dispatch_completed_upload_files,
            duplicate_projection=duplicate_documents_in_project,
        )

    return idempotent(request, idempotency_key, produce, fingerprint_source={"sessionId": session_id, "body": body})


@router.get("/projects/{project_id}/documents/{document_id}")
def document_detail(request: Request, project_id: str, document_id: str):
    document = repo.find_one("documents", document_id)
    read_error = document_read_error(request, project_id, document)
    if read_error:
        return read_error
    versions = repo.versions_for_document(document_id)
    version_ids = {item["id"] for item in versions}
    # O-2：这个端点同时承载元数据（文件名、资料类型、归属节点、OCR 状态、版本、
    # 挂载、抽取字段）与存储签名地址。原先存储不可用时整个端点失败，连「这份资料
    # 是什么、挂在哪个节点」都拿不到——而这些信息完全不依赖对象存储。
    # 现在降级：元数据照常返回，签名地址置空并标注原因，由前端决定是否禁用
    # 预览/下载按钮。
    preview: Any = None
    download: Any = None
    storage_unavailable_reason: str | None = None
    try:
        original = project_document_original_payload(request, project_id, document)
        preview = original["preview"]
        download = original["download"]
    except ObjectStorageUnavailable as exc:
        storage_unavailable_reason = str(exc) or "对象存储不可用"
    return ok(
        {
            "document": attach_document_ocr_readiness(repo, document),
            "currentVersion": repo.current_version(document_id),
            "versions": versions,
            "bindings": [item for item in repo.bindings_for_project(document["projectId"]) if item["documentId"] == document_id],
            "extractedFields": repo.fields_for_versions(version_ids),
            "evidenceLinks": repo.evidence_for_versions(version_ids),
            # OCR 抽出的表格、印章、正文结构。此前只下发 extractedFields，
            # 界面因此只能显示几个字段，而监检核对参数表靠的是表格、
            # 确认盖章靠的是印章——这些后端早就抽出来了，一直没露出来。
            "ocrStructured": build_ocr_structured_view(repo, document),
            "preview": preview,
            "download": download,
            "storageUnavailable": storage_unavailable_reason is not None,
            "storageUnavailableReason": storage_unavailable_reason,
        },
        request,
    )


