@router.get("/projects/{project_id}/documents/{document_id}/review-feedback")
def document_review_feedback(request: Request, project_id: str, document_id: str):
    """该文档所在节点的退回补正往返。

    原实现有两个各自独立的问题：
    1. 返回 repo.state 里**全部**审查意见与整改单，既不按项目也不按文档过滤——
       跨项目的监检结论一并送出；
    2. 绕过了 review_process_read_error。同一份监检人工结论，走
       /inspection/nodes/{id}/review-opinions 时施工方与建设方被 403 拦下，
       走这里却能拿到全文（实测已复现）。角色隔离必须在所有入口一致，
       只在「正门」设卡等于没设。
    """
    process_error = review_process_read_error(request, "监检人工审查意见")
    if process_error:
        return process_error
    scope_error = document_read_scope_error(request, project_id, document_id)
    if scope_error:
        return scope_error
    node_ids = {int(item) for item in document_node_ids(project_id, document_id)}

    def in_scope(item: dict[str, Any]) -> bool:
        if item.get("projectId") != project_id:
            return False
        # 节点无法判定时（历史数据缺 nodeId）不放行——宁可少给，不可多给
        try:
            return int(item.get("nodeId")) in node_ids
        except (TypeError, ValueError):
            return False

    return ok(
        {
            "opinions": [repo.clone(item) for item in repo.state["review_opinions"] if in_scope(item)],
            "rectifications": [repo.clone(item) for item in repo.state["rectifications"] if in_scope(item)],
        },
        request,
    )


@router.post("/projects/{project_id}/documents/{document_id}/versions")
def append_document_version(
    request: Request,
    project_id: str,
    document_id: str,
    body: dict[str, Any] = Body(default_factory=dict),
    x_role: str | None = Header(default=None, alias="X-Role"),
    idempotency_key: str | None = Header(default=None, alias="Idempotency-Key"),
):
    def produce():
        guard = mutation_guard(request, project_id, x_role=x_role, node_ids=document_node_ids(project_id, document_id))
        if guard:
            return guard
        document = repo.find_one("documents", document_id)
        if not document or document.get("projectId") != project_id:
            return fail(errors.NOT_FOUND, request)
        if access_error := document_access_policy.document_mutation_error(_DOCUMENT_ACCESS_SERVICES, request, project_id, document_ids=[document_id]):
            return access_error
        version_id = f"DV-{uuid4().hex[:8].upper()}-V{len(repo.versions_for_document(document_id)) + 1}"
        for version in repo.state["versions"]:
            if version["documentId"] == document_id:
                version["isCurrent"] = False
        version = {
            "id": version_id,
            "documentId": document_id,
            "versionNo": f"V{len(repo.versions_for_document(document_id)) + 1}",
            "hash": body.get("hash"),
            "fileSize": int(body.get("fileSize") or 0),
            "storageKey": body.get("storageKey"),
            "storageBucket": body.get("storageBucket"),
            "ocrStatus": "排队中",
            "sliceStatus": "未切片",
            "vectorStatus": "未向量化",
            "uploaderName": request_actor_name(request),
            "uploadTime": server_time(),
            "isCurrent": True,
        }
        repo.state["versions"].insert(0, version)
        document["currentVersionId"] = version_id
        document["fileStatus"] = "已追加版本" if body.get("mode") == "append" else "已替换"
        document["updatedAt"] = server_time()
        return ok({"version": version, **repo.mutation_result("新增文件版本", "DocumentVersion", version_id, next_status=document["fileStatus"])}, request)

    return idempotent(request, idempotency_key, produce, fingerprint_source={"documentId": document_id, "body": body})


@router.post("/projects/{project_id}/documents/bindings")
def bind_documents(
    request: Request,
    project_id: str,
    body: dict[str, Any] = Body(default_factory=dict),
    idempotency_key: str | None = Header(default=None, alias="Idempotency-Key"),
    x_role: str | None = Header(default=None, alias="X-Role"),
):
    # 每条 binding 自带的 nodeId 必须生效：原先只看 body 顶层的 nodeId/nodeIds，
    # 逐条声明的节点被静默忽略，全部落到施工方的默认节点 16——调用方在界面上选了
    # 节点，资料却挂到别处，且请求返回成功。这也是「大量资料都归到节点 16」的成因之一。
    declared_binding_node_ids = [
        int(item["nodeId"])
        for item in (body.get("bindings") or [])
        if isinstance(item, dict) and str(item.get("nodeId") or "").strip().lstrip("-").isdigit()
    ]
    node_ids = sorted(set(declared_binding_node_ids)) or node_ids_from_body(
        body, ROLE_NODE_MAP["contractor"]
    )

    def produce():
        guard = mutation_guard(request, project_id, x_role=x_role, node_ids=node_ids)
        if guard:
            return guard
        binding_inputs = body.get("bindings") or []
        if not binding_inputs:
            return fail(errors.EMPTY_BINDINGS, request)
        if access_error := document_access_policy.binding_inputs_mutation_error(_DOCUMENT_ACCESS_SERVICES, request, project_id, binding_inputs):
            return access_error
        body_error = unuploaded_document_error(
            request,
            [
                (
                    repo.find_one("documents", item.get("documentId")),
                    repo.find_one("versions", item.get("documentVersionId")) if item.get("documentVersionId") else None,
                )
                for item in binding_inputs
                if item.get("documentId")
            ],
        )
        if body_error:
            return body_error
        created = []
        changed = []
        for node_id in node_ids:
            requirements = [item for item in repo.state["requirements"] if int(item["nodeId"]) == node_id]
            for index, binding_input in enumerate(binding_inputs):
                # 逐条声明了节点时按声明分派，避免每条资料被挂到所有节点上（笛卡尔积）。
                declared = binding_input.get("nodeId") if isinstance(binding_input, dict) else None
                if str(declared or "").strip().lstrip("-").isdigit() and int(declared) != node_id:
                    continue
                document = repo.find_one("documents", binding_input.get("documentId"))
                version_id = binding_input.get("documentVersionId") or (document or {}).get("currentVersionId")
                if not document or not version_id:
                    continue
                requirement = requirements[index % len(requirements)] if requirements else None
                binding = {
                    "id": f"BIND-{node_id}-{uuid4().hex[:6].upper()}",
                    "projectId": project_id,
                    "nodeId": node_id,
                    "requirementId": requirement.get("id") if requirement else None,
                    "requirementName": requirement.get("name") if requirement else None,
                    "documentId": document["id"],
                    "documentVersionId": version_id,
                    "fileName": document["fileName"],
                    "versionNo": (repo.current_version(document["id"]) or {}).get("versionNo") or "--",
                    "usage": binding_input.get("usage") or body.get("usage") or "原始提交",
                    "sourceOrgName": document["sourceOrgName"],
                    "bindingStatus": "草稿挂载",
                    "boundByName": request_actor_name(request),
                    "boundAt": server_time(),
                    "actions": ["submission:submit"],
                }
                repo.state["bindings"].insert(0, binding)
                created.append(binding["id"])
            changed.append(repo.set_node_status(project_id, node_id, "部分提交"))
        return ok(repo.mutation_result("保存节点挂载关系", "NodeFileBinding", created[0] if created else "BIND-EMPTY", next_status="部分提交", changed=changed, affected_ids=created), request)

    return idempotent(
        request,
        idempotency_key,
        produce,
        fingerprint_source=body,
    )


@router.patch("/projects/{project_id}/documents/bindings/{binding_id}")
def update_binding(
    request: Request,
    project_id: str,
    binding_id: str,
    body: dict[str, Any] = Body(default_factory=dict),
    x_role: str | None = Header(default=None, alias="X-Role"),
    idempotency_key: str | None = Header(default=None, alias="Idempotency-Key"),
):
    def produce():
        guard = mutation_guard(request, project_id, x_role=x_role, node_ids=binding_node_ids(project_id, binding_id))
        if guard:
            return guard
        binding = repo.find_one("bindings", binding_id)
        if not binding or binding.get("projectId") != project_id:
            return fail(errors.NOT_FOUND, request)
        if access_error := document_access_policy.document_mutation_error(_DOCUMENT_ACCESS_SERVICES, request, project_id, binding_ids=[binding_id]):
            return access_error
        changed = []
        for field in ["requirementId", "requirementName", "usage", "bindingStatus"]:
            if field in body and binding.get(field) != body[field]:
                changed.append({"field": field, "before": binding.get(field), "after": body[field]})
                binding[field] = body[field]
        return ok({**repo.mutation_result("更新挂载关系", "NodeFileBinding", binding_id, changed=changed), "binding": repo.clone(binding)}, request)

    return idempotent(request, idempotency_key, produce, fingerprint_source={"bindingId": binding_id, "body": body})


@router.delete("/projects/{project_id}/documents/bindings/{binding_id}")
def delete_binding(
    request: Request,
    project_id: str,
    binding_id: str,
    x_role: str | None = Header(default=None, alias="X-Role"),
    idempotency_key: str | None = Header(default=None, alias="Idempotency-Key"),
):
    def produce():
        guard = mutation_guard(request, project_id, x_role=x_role, node_ids=binding_node_ids(project_id, binding_id))
        if guard:
            return guard
        binding = repo.find_one("bindings", binding_id)
        if not binding or binding.get("projectId") != project_id:
            return fail(errors.NOT_FOUND, request)
        if access_error := document_access_policy.document_mutation_error(_DOCUMENT_ACCESS_SERVICES, request, project_id, binding_ids=[binding_id]):
            return access_error
        before = len(repo.state["bindings"])
        repo.state["bindings"] = [item for item in repo.state["bindings"] if item["id"] != binding_id]
        if len(repo.state["bindings"]) == before:
            return fail(errors.NOT_FOUND, request)
        return ok({**repo.mutation_result("解除草稿挂载", "NodeFileBinding", binding_id, next_status="已解除挂载"), "binding": repo.clone(binding)}, request)

    return idempotent(request, idempotency_key, produce, fingerprint_source={"bindingId": binding_id})


@router.delete("/projects/{project_id}/documents/{document_id}")
def delete_project_document(
    request: Request,
    project_id: str,
    document_id: str,
    x_role: str | None = Header(default=None, alias="X-Role"),
    idempotency_key: str | None = Header(default=None, alias="Idempotency-Key"),
):
    def produce():
        guard = mutation_guard(request, project_id, x_role=x_role)
        if guard:
            return guard
        doc = repo.find_one("documents", document_id)
        if not doc or doc.get("projectId") != project_id:
            return fail(errors.NOT_FOUND, request)
        if access_error := document_access_policy.document_mutation_error(_DOCUMENT_ACCESS_SERVICES, request, project_id, document_ids=[document_id]):
            return access_error
        if document_is_locked_from_delete(project_id, document_id):
            return fail(
                errors.CONFLICT,
                request,
                message=(
                    "文件已提交审核，不能直接删除。"
                    "请按撤回或补正流程处理。"
                ),
            )
        removed = remove_project_document_records(project_id, document_id)
        request.state.flush_state_keys = set(PROJECT_DOCUMENT_DELETE_STATE_KEYS)
        return ok(
            {
                **repo.mutation_result(
                    "删除未提交文件",
                    "Document",
                    document_id,
                    next_status="已删除",
                    changed=[
                        {
                            "field": "fileStatus",
                            "before": doc.get("fileStatus"),
                            "after": "已删除",
                        }
                    ],
                ),
                "documentId": document_id,
                "removed": removed,
            },
            request,
        )

    return idempotent(
        request,
        idempotency_key,
        produce,
        fingerprint_source={"documentId": document_id},
    )


