@router.post("/projects/{project_id}/inspection/nodes/{node_id}/file-bindings/submit")
def submit_inspection_file_bindings(
    request: Request,
    project_id: str,
    node_id: int,
    body: dict[str, Any] = Body(default_factory=dict),
    x_role: str | None = Header(default=None, alias="X-Role"),
    idempotency_key: str | None = Header(default=None, alias="Idempotency-Key"),
):
    guard = mutation_guard(request, project_id, x_role=x_role, node_ids=[node_id])
    if guard:
        return guard
    effective_role, role_error = effective_role_for_request(request, x_role)
    if role_error:
        return role_error
    if effective_role != "inspection":
        return fail(errors.FORBIDDEN, request, message="只有监检人员可以提交监检资料。")
    binding_ids = [str(item) for item in body.get("bindingIds") or [] if item]
    if not binding_ids:
        return fail(errors.EMPTY_BINDINGS, request)
    binding_by_id = {
        item["id"]: item
        for item in repo.bindings_for_node(project_id, node_id)
        if item["id"] in set(binding_ids)
    }
    invalid_ids = sorted(set(binding_ids) - set(binding_by_id))
    if invalid_ids:
        return fail(errors.NOT_FOUND, request, data={"invalidBindingIds": invalid_ids})
    invalid_usage_ids = sorted(
        item["id"] for item in binding_by_id.values() if item.get("usage") != "监检资料"
    )
    if invalid_usage_ids:
        return fail(
            errors.FORBIDDEN,
            request,
            message="监检人员只能提交自己形成的监检资料挂载。",
            data={"invalidBindingIds": invalid_usage_ids},
        )
    submission_body = {
        "nodeIds": [node_id],
        "bindingIds": binding_ids,
        "batchName": body.get("batchName") or f"R{node_id:02d} 监检资料",
        "submitterComment": body.get("submitterComment") or "监检人员提交现场或评价证据。",
    }
    return submit_node_package(
        request,
        project_id,
        submission_body,
        idempotency_key=idempotency_key,
        x_role=x_role,
    )


LOCAL_GAP_PRECHECK_FALLBACK_ENV = "AICHECK_ALLOW_LOCAL_GAP_PRECHECK_FALLBACK"


def local_gap_precheck_fallback_policy() -> dict[str, Any]:
    explicit_opt_in = (
        os.getenv(LOCAL_GAP_PRECHECK_FALLBACK_ENV, "").strip().lower() == "true"
    )
    is_strict_production = strict_production()
    return {
        "environmentVariable": LOCAL_GAP_PRECHECK_FALLBACK_ENV,
        "explicitOptIn": explicit_opt_in,
        "strictProduction": is_strict_production,
        "allowed": explicit_opt_in and not is_strict_production,
    }


@router.post("/projects/{project_id}/inspection/nodes/{node_id}/ai-recheck")
def ai_recheck(
    request: Request,
    project_id: str,
    node_id: int,
    body: dict[str, Any] = Body(default_factory=dict),
    idempotency_key: str | None = Header(default=None, alias="Idempotency-Key"),
    x_role: str | None = Header(default=None, alias="X-Role"),
):
    def complete_local_disabled_ai_run(
        run: dict[str, Any],
        *,
        node: dict[str, Any] | None,
        evidence_readiness: dict[str, Any],
        dispatch_readiness: dict[str, Any],
        rule: dict[str, Any],
    ) -> dict[str, Any]:
        blocking_reasons = evidence_readiness.get("blockingReasons") or []
        manual_items = [
            str(item.get("message") or item.get("code"))
            for item in blocking_reasons
            if isinstance(item, dict) and (item.get("message") or item.get("code"))
        ]
        if not manual_items:
            manual_items = ["本地 AI 复核调度未启用，已生成可人工确认的降级复核摘要。"]
        missing_count = int(evidence_readiness.get("missingCount") or 0)
        pending_count = int(evidence_readiness.get("pendingCount") or 0)
        evidence_count = len(run.get("evidenceLinks") or [])
        rule_label = rule.get("ruleKey") or rule.get("id") or run.get("ruleVersion") or "未配置规则"
        node_name = (node or {}).get("name") or run.get("subject") or f"节点 {run.get('nodeId')}"
        conclusion = "需补正" if missing_count else "需人工确认"
        opinion = (
            f"AI 复核已生成本地降级结果：节点“{node_name}”当前命中 {evidence_count} 条候选证据，"
            f"缺项 {missing_count} 项，待确认证据 {pending_count} 项。请结合右侧证据链、OCR 字段和规则要求完成人工确认。"
        )
        reasoning = "\n".join(
            [
                "本地降级复核摘要（未调用外部模型）",
                f"1. 读取项目节点：{node_name}。",
                f"2. 对齐业务规则：{rule_label}，规则版本 {run.get('ruleVersion') or '-'}。",
                f"3. 汇总资料证据：候选证据 {evidence_count} 条，输入文档版本 {len(run.get('inputDocumentVersionIds') or [])} 个。",
                f"4. 检查资料就绪度：必传 {evidence_readiness.get('requiredCount', 0)} 项，满足 {evidence_readiness.get('satisfiedCount', 0)} 项，缺项 {missing_count} 项，待人工处理 {pending_count} 项。",
                "5. 当前调度器未启用，未调用外部模型；系统按证据就绪度、规则上下文和人工确认边界生成复核摘要。",
                f"6. 建议结论：{conclusion}；原因：" + "；".join(manual_items[:5]),
            ]
        )
        run["status"] = "完成"
        run["finishedAt"] = server_time()
        run["suggestion"] = {
            **(run.get("suggestion") or {}),
            "result": conclusion,
            "opinionDraft": opinion,
            # 本地降级路径同样不给常量（N-3）：按「已就绪的证据项占比」派生。
            "confidence": local_review_confidence(missing_count, pending_count, len(manual_items)),
            "manualConfirmItems": manual_items,
        }
        run["reasoningProcess"] = reasoning
        run["llmResultText"] = opinion
        run["llmMetadata"] = {
            "llmExecution": "local_disabled_fallback",
            "llmCalled": False,
            "reasoningProcess": reasoning,
            "deepThinkAvailable": False,
            "resultText": opinion,
            "dispatchReadiness": repo.clone(dispatch_readiness),
            "groundingInputSummary": {
                "evidenceLinkCount": evidence_count,
                "missingCount": missing_count,
                "pendingCount": pending_count,
            },
        }
        run["promptAudit"] = {
            "promptVersion": run.get("promptVersion"),
            "ruleVersion": run.get("ruleVersion"),
            "messagesHash": stable_hash_payload(
                {
                    "projectId": run.get("projectId"),
                    "nodeId": run.get("nodeId"),
                    "inputDocumentVersionIds": run.get("inputDocumentVersionIds") or [],
                    "evidenceReadiness": evidence_readiness,
                }
            ),
            "payloadPolicy": "local_disabled_fallback_summary",
        }
        run["findingDrafts"] = [
            {
                "id": f"FND-DRAFT-{run['id']}",
                "projectId": run.get("projectId"),
                "nodeId": run.get("nodeId"),
                "findingType": "ai_review_suggestion",
                "severity": "medium" if missing_count or pending_count else "low",
                "title": "AI 本地降级复核摘要",
                "description": opinion,
                "evidenceLinkIds": [item.get("id") for item in (run.get("evidenceLinks") or [])[:3] if isinstance(item, dict) and item.get("id")],
                "ruleRefs": [{"ruleCode": rule_label, "ruleSetVersion": run.get("ruleVersion")}],
                "confidence": run["suggestion"]["confidence"],
                "suggestedAction": "human_confirm",
                "requiresHumanConfirmation": True,
                "status": "pending_human_review",
                "createdAt": run["finishedAt"],
            }
        ]
        return run

    def produce():
        guard = mutation_guard(request, project_id, x_role=x_role, node_ids=[node_id])
        if guard:
            return guard
        run_id = f"AIRUN-{node_id}-{uuid4().hex[:8].upper()}"
        node = repo.node(project_id, node_id)
        project = repo.require_project(project_id)
        pack = business_pack_for_project(project)
        agent = (pack.get("agentSops") or [{}])[0]
        try:
            audit_runtime = audit_runtime_public_config(
                mode=str(body.get("auditInputMode") or body.get("auditRuntimeMode") or "") or None
            )
        except RuntimeError as exc:
            return fail(errors.VALIDATION_ERROR, request, message=str(exc))
        evidence_readiness = build_node_evidence_readiness(repo, project_id, node_id)
        requested_review_mode = str(body.get("reviewMode") or "").strip().lower()
        if requested_review_mode and requested_review_mode not in {"formal", "gap_precheck"}:
            return fail(
                errors.VALIDATION_ERROR,
                request,
                message="reviewMode 仅支持 formal 或 gap_precheck。",
            )
        if audit_runtime["mode"] == "pure_llm" and requested_review_mode == "formal":
            return fail(
                errors.CONFLICT,
                request,
                message="pure_llm 只能用于缺项预审，不能发起正式 AI 复核。",
                data={"evidenceReadiness": evidence_readiness, "advisoryOnly": True},
                http_status=409,
            )
        review_mode = requested_review_mode
        if not review_mode:
            if audit_runtime["mode"] == "pure_llm":
                review_mode = "gap_precheck"
            elif evidence_readiness.get("readyForAiFormal"):
                review_mode = "formal"
            elif evidence_readiness.get("readyForGapPrecheck"):
                review_mode = "gap_precheck"
        if review_mode == "formal" and not evidence_readiness.get("readyForAiFormal"):
            return fail(
                errors.CONFLICT,
                request,
                message="资料证据未满足正式 AI 复核条件，请先处理阻断项或使用缺项预审。",
                data={"evidenceReadiness": evidence_readiness, "requestedReviewMode": review_mode},
                http_status=409,
            )
        binding_set = pack.get("atomicCheckToolBindingSet") or {}
        binding_lifecycle = str(binding_set.get("lifecycleStatus") or "draft").lower()
        node_rule_for_binding = next(
            (item for item in pack.get("ruleSets") or [] if node_id in set(item.get("nodeIds") or [])),
            {},
        )
        node_source_rule_id = str(
            node_rule_for_binding.get("sourceRuleId")
            or node_rule_for_binding.get("id")
            or node_rule_for_binding.get("ruleKey")
            or ""
        )
        pilot_rules = {str(item) for item in binding_set.get("pilotRules") or [] if item}
        pilot_rule_enabled = node_source_rule_id in pilot_rules
        if review_mode == "formal" and binding_lifecycle != "published" and not pilot_rule_enabled:
            return fail(
                errors.CONFLICT,
                request,
                message="当前节点的原子检查工具绑定尚未发布或启用试点，不能发起正式 AI 复核。",
                data={
                    "bindingSetId": binding_set.get("id"),
                    "bindingSetVersion": binding_set.get("version"),
                    "lifecycleStatus": binding_lifecycle,
                    "sourceRuleId": node_source_rule_id,
                    "pilotRuleEnabled": pilot_rule_enabled,
                    "allowedReviewMode": "gap_precheck",
                },
                http_status=409,
            )
        if review_mode == "gap_precheck" and not (
            evidence_readiness.get("readyForGapPrecheck") or audit_runtime["mode"] == "pure_llm"
        ):
            return fail(
                errors.CONFLICT,
                request,
                message="当前节点没有可执行缺项预审的审查点，请联系 FDE 完成规则配置。",
                data={"evidenceReadiness": evidence_readiness, "requestedReviewMode": review_mode},
                http_status=409,
            )
        if not review_mode:
            return fail(
                errors.CONFLICT,
                request,
                message="当前节点没有可用的 AI 复核模式。",
                data={"evidenceReadiness": evidence_readiness},
                http_status=409,
            )
        advisory_only = review_mode == "gap_precheck" or audit_runtime["mode"] == "pure_llm"
        previous_node_status = str((node or {}).get("status") or "")
        node_evidence_links = [
            link
            for link in node_evidence_links_for_node(repo, project_id, node_id)
            if str(link.get("manualStatus") or "").lower() != "rejected"
        ]
        input_document_version_ids = sorted({str(link.get("documentVersionId")) for link in node_evidence_links if link.get("documentVersionId")})
        if not input_document_version_ids:
            input_document_version_ids = targeting_input_versions_for_node(repo, project_id, node_id)
        rule = (
            current_business_rule_for_node(node_id, business_pack_id=pack["id"])
            or next(
                (item for item in pack.get("ruleSets") or [] if node_id in set(item.get("nodeIds") or [])),
                (pack.get("ruleSets") or [{}])[0],
            )
        )
        clause_package_snapshot = clause_package_snapshot_for_project_node(
            repo.state,
            project_id,
            node_id,
        )
        if pack.get("standardClausePackages") and not clause_package_snapshot:
            return fail(
                errors.CONFLICT,
                request,
                message="当前项目节点尚未绑定已发布的数据库条款包，请先同步业务包条款数据。",
                data={"projectId": project_id, "nodeId": node_id, "businessPackVersion": pack.get("version")},
                http_status=409,
            )
        run = {
            "id": run_id,
            "projectId": project_id,
            "nodeId": node_id,
            "businessPackId": pack["id"],
            "businessPackVersion": pack["version"],
            "businessPackSnapshotHash": pack["snapshotHash"],
            "atomicCheckToolBindingSetId": binding_set.get("id"),
            "atomicCheckToolBindingSetVersion": binding_set.get("version"),
            "atomicCheckToolBindingSetLifecycle": binding_lifecycle,
            "atomicCheckToolBindingSetHash": stable_hash_payload(
                {
                    "metadata": binding_set,
                    "bindings": pack.get("atomicCheckToolBindings") or [],
                }
            ),
            "atomicCheckToolBindingSetSnapshot": repo.clone(binding_set),
            "atomicCheckToolBindingsSnapshot": repo.clone(pack.get("atomicCheckToolBindings") or []),
            "clausePackageId": (clause_package_snapshot or {}).get("packageStorageId"),
            "clausePackageSnapshotHash": (clause_package_snapshot or {}).get("snapshotHash"),
            "clausePackageSnapshot": clause_package_snapshot,
            "agentId": agent.get("id") or "review_agent",
            "agentVersion": agent.get("version") or "1.0.0",
            "subject": node["name"] if node else "节点 AI 复核",
            "model": "review-chat",
            "auditInputMode": audit_runtime["mode"],
            "auditRuntime": audit_runtime,
            "reviewMode": review_mode,
            "advisoryOnly": advisory_only,
            "confidenceScale": "ratio",
            "promptVersion": f"node-{node_id}-v1",
            "ruleVersion": rule.get("version") or "ruleset-v1",
            "inputDocumentVersionIds": input_document_version_ids,
            "evidenceReadiness": evidence_readiness,
            "status": "推理中",
            "startedAt": server_time(),
            "operationId": getattr(request.state, "operation_id", None),
            "previousNodeStatus": previous_node_status,
            "stateTransition": {
                "from": previous_node_status,
                "to": previous_node_status,
                "reason": "gap_precheck_does_not_change_node_status" if advisory_only else "queued",
            },
            "steps": [],
            "suggestion": {
                "id": f"AIS-{uuid4().hex[:8].upper()}",
                "result": "需人工确认",
                "opinionDraft": "AI 复核任务已进入队列，完成后将更新审查建议。",
                "risks": [],
                "confidence": 0.0,
                "manualConfirmItems": [],
            },
            "evidenceLinks": node_evidence_links,
            "findingDrafts": [],
        }
        dispatch_readiness = task_dispatcher.ai_recheck_dispatch_readiness()
        if not dispatch_readiness.get("ready"):
            if review_mode == "formal":
                return fail(
                    errors.CONFLICT,
                    request,
                    message="正式 AI 复核调度不可用，节点状态未变更。",
                    data={
                        "dispatch": dispatch_readiness,
                        "evidenceReadiness": evidence_readiness,
                        "requestedReviewMode": review_mode,
                    },
                    http_status=409,
                )
            fallback_policy = local_gap_precheck_fallback_policy()
            if not fallback_policy["allowed"]:
                return fail(
                    errors.CONFLICT,
                    request,
                    message="缺项预审调度不可用，本地降级未按部署策略启用，节点状态未变更。",
                    data={
                        "dispatch": dispatch_readiness,
                        "evidenceReadiness": evidence_readiness,
                        "requestedReviewMode": review_mode,
                        "fallbackPolicy": fallback_policy,
                    },
                    http_status=409,
                )
            complete_local_disabled_ai_run(
                run,
                node=node,
                evidence_readiness=evidence_readiness,
                dispatch_readiness=dispatch_readiness,
                rule=rule,
            )
            repo.state["ai_runs"].insert(0, run)
            dispatch = {
                **dispatch_readiness,
                "mode": "local_disabled_fallback",
                "result": "completed_without_external_dispatch",
            }
            return ok(
                {
                    "runId": run_id,
                    "status": run["status"],
                    "latestRun": run,
                    "reviewMode": review_mode,
                    "advisoryOnly": advisory_only,
                    "stateTransition": run["stateTransition"],
                    "dispatch": dispatch,
                },
                request,
            )
        repo.state["ai_runs"].insert(0, run)
        dispatch = task_dispatcher.dispatch_ai_recheck(project_id, node_id, run_id)
        if dispatch.get("status") == "failed_to_start":
            run["status"] = "失败"
            run["errorCode"] = str(dispatch.get("errorCode") or "TASK_DISPATCH_UNAVAILABLE")
            run["errorMessage"] = str(dispatch.get("message") or "AI 复核编排启动失败。")
            run["finishedAt"] = server_time()
            if dispatch.get("reviewRunId"):
                run["reviewRunId"] = dispatch.get("reviewRunId")
            if dispatch.get("workflowId"):
                run["workflowId"] = dispatch.get("workflowId")
            return fail(
                errors.AI_RUN_FAILED,
                request,
                message="AI 复核编排启动失败，节点状态未变更。",
                data={"dispatch": dispatch, "latestRun": run},
                http_status=503,
            )
        if not dispatch.get("taskId") and not dispatch.get("result") and not dispatch.get("reviewRunId") and not dispatch.get("workflowId"):
            run["status"] = "失败"
            run["errorCode"] = "TASK_DISPATCH_UNAVAILABLE"
            run["errorMessage"] = "AI 复核任务调度未创建可执行任务。"
            run["finishedAt"] = server_time()
            return fail(
                errors.CONFLICT,
                request,
                message="AI 复核任务调度未创建可执行任务，节点状态未变更。",
                data={"dispatch": dispatch, "latestRun": run},
            )
        dispatch.setdefault(
            "statusReason",
            "缺项预审已进入队列" if advisory_only else "正式 AI 复核已进入队列",
        )
        if dispatch.get("taskId"):
            run["taskId"] = dispatch.get("taskId")
        if not advisory_only:
            repo.set_node_status(project_id, node_id, "业务核验中")
            run["stateTransition"] = {
                "from": previous_node_status,
                "to": "业务核验中",
                "reason": "formal_review_dispatched",
            }
        if dispatch.get("reviewRunId"):
            run["reviewRunId"] = dispatch.get("reviewRunId")
        if dispatch.get("workflowId"):
            run["workflowId"] = dispatch.get("workflowId")
        review_run_id = str(run.get("reviewRunId") or "")
        if review_run_id:
            request.state.scoped_flush_records = lambda: review_run_state_records(review_run_id)
        return ok(
            {
                "runId": run_id,
                "status": run["status"],
                "latestRun": run,
                "reviewMode": review_mode,
                "advisoryOnly": advisory_only,
                "stateTransition": run["stateTransition"],
                "dispatch": dispatch,
            },
            request,
        )

    return idempotent(
        request,
        idempotency_key,
        produce,
        fingerprint_source={
            "projectId": project_id,
            "nodeId": node_id,
            "auditInputMode": body.get("auditInputMode") or body.get("auditRuntimeMode"),
            "reviewMode": body.get("reviewMode"),
        },
    )


@router.get("/projects/{project_id}/inspection/nodes/{node_id}/live-status")
def node_live_status(request: Request, project_id: str, node_id: int):
    """轮询专用的轻量状态接口。

    界面在 AI 复核和上传处理期间需要定时探活。此前轮询直接重拉 nodes/{id}/package
    （含全量 AI 运行历史，实测约 665KB）并整体替换数据，导致页面反复整体重绘。
    这里只回状态字段，让轮询判断"是否还在进行中"，仅在状态变化时才去取完整数据。
    """
    scope_error = member_node_scope_error(
        request, project_id, effective_role_for_request(request)[0], node_ids=[node_id]
    )
    if scope_error:
        return scope_error
    tenant_id = request_tenant_id(request)
    node_runs = [
        item
        for item in repo.state.get("ai_runs", [])
        if item.get("projectId") == project_id
        and int(item.get("nodeId") or 0) == int(node_id)
        and tenant_id_for_record(item) == tenant_id
    ]
    latest = node_runs[0] if node_runs else None
    node = repo.node(project_id, node_id) or {}
    document_repo = repo.project_document_read_view(project_id)
    documents = [
        item
        for item in visible_project_documents_for_request(
            request,
            project_id,
            document_repo=document_repo,
        )
        if any(
            binding.get("projectId") == project_id
            and binding.get("documentId") == item.get("id")
            and int(binding.get("nodeId") or 0) == int(node_id)
            for binding in document_repo.state.get("bindings", [])
        )
        or int(item.get("nodeId") or 0) == int(node_id)
    ]
    processing = [
        {
            "documentId": item.get("id"),
            "fileName": item.get("fileName"),
            "ocrStatus": item.get("currentOcrStatus"),
            "sliceStatus": item.get("sliceStatus"),
            "vectorStatus": item.get("vectorStatus"),
        }
        for item in documents
        if str(item.get("currentOcrStatus") or "") not in {"", "已识别", "人工修正", "抽取不完整"}
    ]
    return ok(
        {
            "nodeId": int(node_id),
            "nodeStatus": node.get("status"),
            "nodeRevision": node.get("revision"),
            "latestAiRun": (
                {
                    "id": latest.get("id"),
                    "status": latest.get("status"),
                    "reviewMode": latest.get("reviewMode"),
                    "suggestionResult": (latest.get("suggestion") or {}).get("result"),
                    "finishedAt": latest.get("finishedAt"),
                }
                if latest
                else None
            ),
            "processingDocumentCount": len(processing),
            "processingDocuments": processing[:20],
        },
        request,
    )


@router.get("/projects/{project_id}/inspection/nodes/{node_id}/ai-runs")
def list_ai_runs(request: Request, project_id: str, node_id: int):
    process_error = review_process_read_error(request, "AI 复核过程记录")
    if process_error:
        return process_error
    scope_error = member_node_scope_error(request, project_id, effective_role_for_request(request)[0], node_ids=[node_id])
    if scope_error:
        return scope_error
    return ok(
        [
            safe_ai_run_view(item)
            for item in repo.state["ai_runs"]
            if item["projectId"] == project_id
            and int(item["nodeId"]) == int(node_id)
            and tenant_id_for_record(item) == request_tenant_id(request)
        ],
        request,
    )


@router.get("/projects/{project_id}/inspection/nodes/{node_id}/ai-runs/{run_id}")
def get_ai_run(request: Request, project_id: str, node_id: int, run_id: str):
    run = repo.find_one("ai_runs", run_id)
    if (
        not run
        or str(run.get("projectId") or "") != project_id
        or int(run.get("nodeId") or 0) != int(node_id)
    ):
        return fail(errors.NOT_FOUND, request)
    scope_error = scope_error_for_record(request, run, project_id)
    if scope_error:
        return scope_error
    return ok(safe_ai_run_view(run), request)


REVIEW_SESSION_TERMINAL_RUN_STATUSES = {
    "accepted_by_human",
    "edited_by_human",
    "rejected_by_human",
    "failed",
    "cancelled",
}


def ensure_review_session_state() -> None:
    repo.state.setdefault("review_sessions", [])
    repo.state.setdefault("review_messages", [])
    repo.state.setdefault("review_session_events", [])
    repo.state.setdefault("agent_executions", [])
    repo.state.setdefault("review_session_tool_memory", [])


def persist_review_session_records(**records_by_state_key: list[dict[str, Any]]) -> None:
    """把会话相关记录即时提交到共享持久化存储。

    多 worker 部署下，SSE/轮询读取端点通过 live-read refresh 从 Postgres 取事件与消息，
    因此写入方必须在产生记录时立即定向落库，而不是等请求结束的整体 flush。
    即时同步失败不中断业务（请求级 flush 仍是兜底）。
    """
    if not postgres_persistence_configured():
        return
    payload = {
        state_key: [repo.clone(item) for item in items if isinstance(item, dict)]
        for state_key, items in records_by_state_key.items()
        if items
    }
    if not payload:
        return
    try:
        flush_mutation_records(payload, [])
    except Exception:  # noqa: BLE001 - 定向同步失败时由请求级 flush 兜底
        pass


def review_session_view(session: dict[str, Any]) -> dict[str, Any]:
    view = repo.clone(session)
    view["revision"] = record_revision(session)
    view["etag"] = record_etag("review-session", session)
    return view


def active_review_session(
    request: Request,
    project_id: str,
    node_id: int,
) -> dict[str, Any] | None:
    ensure_review_session_state()
    user_id = request_user_id(request) or "USER-UNKNOWN"
    return next(
        (
            item
            for item in repo.state["review_sessions"]
            if item.get("projectId") == project_id
            and int(item.get("nodeId") or 0) == int(node_id)
            and item.get("createdBy") == user_id
            and item.get("status") == "active"
            and tenant_id_for_record(item) == request_tenant_id(request)
        ),
        None,
    )


def review_session_scope_error(request: Request, session: dict[str, Any]) -> JSONResponse | None:
    project_id = str(session.get("projectId") or "")
    node_id = int(session.get("nodeId") or 0)
    scope_error = scope_error_for_record(request, session, project_id)
    if scope_error:
        return scope_error
    return inspection_review_scope_error(request, project_id, node_id)


def inspection_review_scope_error(
    request: Request,
    project_id: str,
    node_id: int,
) -> JSONResponse | None:
    role, identity_error = effective_role_for_request(request)
    if identity_error:
        return identity_error
    if role != "inspection":
        return fail(
            errors.FORBIDDEN,
            request,
            message="仅监检人员可使用 AI 复核 B 版。",
            http_status=403,
        )
    return member_node_scope_error(request, project_id, role, node_ids=[node_id])


def review_session_precondition_error(
    request: Request,
    session: dict[str, Any],
    if_match: str | None,
) -> JSONResponse | None:
    if not if_match:
        return fail(
            errors.PRECONDITION_REQUIRED,
            request,
            message="ReviewSession 更新必须携带 GET 返回的 etag（If-Match）。",
            data={"etag": record_etag("review-session", session)},
            http_status=428,
        )
    if not record_if_match_valid("review-session", session, if_match):
        return fail(
            errors.ETAG_CONFLICT,
            request,
            data={
                "etag": record_etag("review-session", session),
                "revision": record_revision(session),
            },
            http_status=409,
        )
    return None


def next_review_session_sequence(collection: str, session_id: str) -> int:
    return (
        max(
            (
                int(item.get("sequence") or 0)
                for item in repo.state.get(collection, [])
                if item.get("sessionId") == session_id
            ),
            default=0,
        )
        + 1
    )


def append_review_session_event(
    session: dict[str, Any],
    *,
    event_type: str,
    title: str,
    payload: dict[str, Any] | None = None,
    review_run_id: str | None = None,
) -> dict[str, Any]:
    ensure_review_session_state()
    event = {
        "id": f"RSEVT-{uuid4().hex[:10].upper()}",
        "schema": "review-event/v1",
        "sessionId": session["id"],
        "projectId": session["projectId"],
        "nodeId": session["nodeId"],
        "reviewRunId": review_run_id or session.get("activeReviewRunId"),
        "sequence": next_review_session_sequence("review_session_events", session["id"]),
        "eventType": event_type,
        "title": title,
        "payload": repo.clone(payload or {}),
        "payloadHash": stable_hash_payload(payload or {}),
        "createdAt": server_time(),
    }
    repo.state["review_session_events"].append(event)
    # 事件即时落库：后台执行线程产生的事件必须立刻对其他 worker 的 SSE/轮询可见。
    persist_review_session_records(review_session_events=[event])
    return event


def latest_review_run_for_node(
    project_id: str,
    node_id: int,
    *,
    review_run_id: str | None = None,
) -> dict[str, Any] | None:
    project = repo.require_project(project_id) or {}
    project_tenant_id = tenant_id_for_record(project)
    runs = [
        item
        for item in repo.state.get("review_runs", [])
        if item.get("projectId") == project_id
        and int(item.get("nodeId") or 0) == int(node_id)
        and tenant_id_for_record(item) == project_tenant_id
    ]
    if review_run_id:
        selected = next(
            (
                item
                for item in runs
                if str(item.get("reviewRunId") or item.get("id") or "") == review_run_id
            ),
            None,
        )
        if selected:
            return selected
    return next(
        (
            item
            for item in runs
            if str(item.get("status") or "").lower() not in REVIEW_SESSION_TERMINAL_RUN_STATUSES
        ),
        runs[0] if runs else None,
    )


def active_human_input_task_for_run(review_run: dict[str, Any] | None) -> dict[str, Any] | None:
    if not review_run:
        return None
    return next(
        (
            repo.clone(item)
            for item in reversed(review_run.get("humanInputTasks") or [])
            if isinstance(item, dict) and item.get("status") == "pending"
        ),
        None,
    )


def review_workspace_payload(
    request: Request,
    project_id: str,
    node_id: int,
    *,
    review_run_id: str | None = None,
) -> dict[str, Any]:
    ensure_review_session_state()
    project = repo.require_project(project_id) or {}
    project_bindings = repo.bindings_for_project(project_id)
    node = repo.node(project_id, node_id) or {}
    node_view = enrich_node_with_requirements_summary(
        project_id,
        node,
        project_bindings=project_bindings,
    )
    evidence_readiness = build_node_evidence_readiness(repo, project_id, node_id)
    evidence_links = [
        repo.clone(item)
        for item in evidence_readiness.get("nodeEvidenceLinks", [])
        if record_visible_for_request(request, item)
    ]
    session = active_review_session(request, project_id, node_id)
    selected_run_id = review_run_id or str((session or {}).get("activeReviewRunId") or "") or None
    review_run = latest_review_run_for_node(
        project_id,
        node_id,
        review_run_id=selected_run_id,
    )
    run_id = str((review_run or {}).get("reviewRunId") or (review_run or {}).get("id") or "")
    if session and run_id:
        selected_run_id = run_id
    basis = node_business_basis(project, node_id) or {}
    fixed_basis = fixed_standard_references_for_node(project, node_id)
    selected_evidence_ids = set((session or {}).get("selectedEvidenceLinkIds") or [])
    selected_evidence = [item for item in evidence_links if item.get("id") in selected_evidence_ids]
    active_task = active_human_input_task_for_run(review_run)
    # 按时间倒序：latestHumanDecision 取的是 [0]，不排序拿到的是**最早**那条。
    #
    # 2026-08-15 实测：刚存下 22:10 的结论，界面上「已保存」显示的是 11:17 的旧结论。
    # 这比不显示更糟——它会把一条过期结论当成当前结论摆在监检面前。
    review_opinions = sorted(
        (
            repo.clone(item)
            for item in repo.state.get("review_opinions", [])
            if item.get("projectId") == project_id and int(item.get("nodeId") or 0) == int(node_id)
        ),
        key=lambda item: str(item.get("updatedAt") or item.get("createdAt") or ""),
        reverse=True,
    )
    role = effective_role_for_request(request)[0] or "inspection"
    can_review = role in {"inspection", "admin", "fde"}
    can_return_correction = "review:return-correction" in repo.role_actions(role)
    returnable_bindings = []
    for binding in project_bindings:
        if (
            int(binding.get("nodeId") or 0) != int(node_id)
            or binding.get("bindingStatus") != "已提交"
        ):
            continue
        document = repo.find_one("documents", str(binding.get("documentId") or "")) or {}
        returnable_bindings.append(
            {
                "id": binding.get("id"),
                "documentId": binding.get("documentId"),
                "fileName": binding.get("fileName") or document.get("fileName"),
                "materialTypeName": document.get("materialTypeName"),
                "materialCategory": document.get("materialCategory"),
                "bindingStatus": binding.get("bindingStatus"),
            }
        )
    run_status = str((review_run or {}).get("status") or "")
    available_modes = evidence_readiness.get("availableReviewModes") or []
    current_task = str((session or {}).get("currentTask") or basis.get("inspectionItem") or node.get("name") or "")
    last_event_sequence = len(review_run_timeline(run_id)) if run_id else 0
    return {
        "schemaVersion": "ReviewWorkspaceProjection@1.0.0",
        "workspaceRevision": max(record_revision(session or {}) if session else 1, record_revision(review_run or {}) if review_run else 1),
        "project": versioned_project(project),
        "node": repo.clone(node_view),
        "permissions": {
            "canStartReview": can_review and bool(available_modes),
            "canSubmitHumanInput": can_review and bool(active_task),
            "canSubmitHumanDecision": can_review and run_status == "waiting_human_review",
            "canSubmitReviewOpinion": can_review,
            "canReturnCorrection": can_return_correction,
            "canManageEvidence": can_review,
        },
        "evidenceReadiness": repo.clone(evidence_readiness),
        "evidenceLinks": evidence_links,
        "selectedEvidence": selected_evidence,
        "returnableBindings": returnable_bindings,
        "businessBasis": repo.clone(basis),
        "basisSnapshot": fixed_basis,
        "session": review_session_view(session) if session else None,
        "activeReviewRun": review_run_view(review_run) if review_run else None,
        "activeHumanInputTask": active_task,
        "latestHumanDecision": (
            repo.clone(review_opinions[0])
            if review_opinions
            else repo.clone((review_run or {}).get("humanDecision"))
        ),
        "contextSummary": {
            "currentTask": current_task,
            "selectedEvidenceCount": len(selected_evidence),
            "confirmedEvidenceCount": sum(1 for item in evidence_links if item.get("manualStatus") == "confirmed"),
            "processTodoCount": 1 if active_task else 0,
            "finalReviewTodoCount": 1 if run_status == "waiting_human_review" else 0,
        },
        "lastEventSequence": last_event_sequence,
        "updatedAt": server_time(),
    }


@router.get("/projects/{project_id}/inspection/nodes/{node_id}/review-workspace")
def get_review_workspace(
    request: Request,
    project_id: str,
    node_id: int,
    reviewRunId: str | None = Query(default=None),
):
    project = repo.require_project(project_id)
    node = repo.node(project_id, node_id)
    if not project or not node:
        return fail(errors.NOT_FOUND, request)
    scope_error = inspection_review_scope_error(request, project_id, node_id)
    if scope_error:
        return scope_error
    return ok(
        review_workspace_payload(request, project_id, node_id, review_run_id=reviewRunId),
        request,
    )


@router.get("/projects/{project_id}/inspection/nodes/{node_id}/review-sessions/active")
def get_active_node_review_session(request: Request, project_id: str, node_id: int):
    scope_error = inspection_review_scope_error(request, project_id, node_id)
    if scope_error:
        return scope_error
    session = active_review_session(request, project_id, node_id)
    return ok({"session": review_session_view(session) if session else None}, request)


@router.post("/projects/{project_id}/inspection/nodes/{node_id}/review-sessions")
def create_node_review_session(
    request: Request,
    project_id: str,
    node_id: int,
    body: dict[str, Any] = Body(default_factory=dict),
    idempotency_key: str | None = Header(default=None, alias="Idempotency-Key"),
):
    def produce():
        guard = mutation_guard(request, project_id, node_ids=[node_id])
        if guard:
            return guard
        project = repo.require_project(project_id)
        node = repo.node(project_id, node_id)
        if not project or not node:
            return fail(errors.NOT_FOUND, request)
        scope_error = inspection_review_scope_error(request, project_id, node_id)
        if scope_error:
            return scope_error
        existing = active_review_session(request, project_id, node_id)
        if existing:
            return ok({"session": review_session_view(existing), "created": False}, request)
        current_task, task_error = validated_plain_text(
            body.get("currentTask") or node.get("name"),
            limit=300,
            field_name="当前任务",
        )
        if task_error:
            return fail(errors.VALIDATION_ERROR, request, message=task_error)
        now = server_time()
        confirmed_evidence_ids = [
            str(item.get("id"))
            for item in build_node_evidence_readiness(repo, project_id, node_id).get("nodeEvidenceLinks", [])
            if item.get("id") and item.get("manualStatus") == "confirmed"
        ]
        session = {
            "id": f"RSESSION-{uuid4().hex[:10].upper()}",
            "projectId": project_id,
            "nodeId": node_id,
            "role": effective_role_for_request(request)[0] or "inspection",
            "status": "active",
            "currentTask": current_task,
            "activeReviewRunId": body.get("reviewRunId"),
            "selectedEvidenceLinkIds": confirmed_evidence_ids,
            "selectedJudgmentIds": [],
            "contextRevision": 1,
            "revision": 1,
            "createdBy": request_user_id(request) or "USER-UNKNOWN",
            "createdByName": request_actor_name(request),
            "tenantId": request_tenant_id(request),
            "createdAt": now,
            "updatedAt": now,
        }
        repo.state["review_sessions"].insert(0, session)
        append_review_session_event(
            session,
            event_type="session.created",
            title="AI 复核会话已建立",
            payload={"currentTask": current_task},
        )
        return ok({"session": review_session_view(session), "created": True}, request)

    return idempotent(
        request,
        idempotency_key,
        produce,
        fingerprint_source={"projectId": project_id, "nodeId": node_id, "body": body},
    )


def review_message_view(message: dict[str, Any]) -> dict[str, Any]:
    return repo.clone(message)


