def archive_package_export_id(project_id: str) -> str:
    return f"EXP-ARCHIVE-{stable_hash_payload(project_id)[7:17].upper()}"


def evidence_package_export_id(project_id: str, scope_id: Any) -> str:
    return f"EXP-EVIDENCE-{stable_hash_payload({'projectId': project_id, 'scopeId': scope_id})[7:17].upper()}"


def project_document_lookup(project_id: str) -> tuple[set[str], set[str]]:
    document_ids = {
        str(item.get("id"))
        for item in repo.state.get("documents", [])
        if item.get("projectId") == project_id and item.get("id")
    }
    version_ids = {
        str(item.get("id"))
        for item in repo.state.get("versions", [])
        if item.get("documentId") in document_ids and item.get("id")
    }
    return document_ids, version_ids


def node_document_version_ids(project_id: str, node_id: int) -> set[str]:
    return {
        str(item.get("documentVersionId"))
        for item in repo.state.get("bindings", [])
        if item.get("projectId") == project_id
        and int(item.get("nodeId") or 0) == int(node_id)
        and item.get("documentVersionId")
    }


def archive_package_rows(project_id: str, scope: set[int] | None) -> list[dict[str, Any]]:
    return [
        repo.clone(item)
        for item in repo.state["archive_items"]
        if item.get("projectId") == project_id and archive_visible_in_scope(item, scope)
    ]


def evidence_package_rows(
    project_id: str,
    *,
    node_id: int | None = None,
    report_id: str | None = None,
) -> list[dict[str, Any]]:
    if report_id:
        report = repo.find_one("reports", report_id)
        if not report or report.get("projectId") != project_id:
            return []
        return report_evidence_links(report)
    if node_id is not None:
        return confirmed_node_evidence_scope(project_id, node_id)["evidenceLinks"]
    return []


def package_csv(rows: list[dict[str, Any]], columns: list[str]) -> str:
    def cell(value: Any) -> str:
        text = str(value if value is not None else "")
        return f'"{text.replace(chr(34), chr(34) + chr(34))}"' if re.search(r'[",\n\r]', text) else text

    lines = [",".join(columns)]
    for row in rows:
        lines.append(",".join(cell(row.get(column)) for column in columns))
    return "\n".join(lines) + "\n"


def build_archive_zip_artifact(*, manifest: dict[str, Any], files: dict[str, Any]) -> bytes:
    buffer = io.BytesIO()
    with zipfile.ZipFile(buffer, "w", compression=zipfile.ZIP_DEFLATED) as package:
        package.writestr("manifest.json", json.dumps(manifest, ensure_ascii=False, indent=2))
        for path, payload in files.items():
            if isinstance(payload, bytes) or isinstance(payload, str):
                package.writestr(path, payload)
            else:
                package.writestr(path, json.dumps(payload, ensure_ascii=False, indent=2))
        package.writestr(
            "README.txt",
            "AIcheck export package. See manifest.json for lineage, counts, integrity hashes and included files.\n",
        )
    return buffer.getvalue()


@router.get("/projects/{project_id}/archive/package")
def archive_package(request: Request, project_id: str):
    role_error = archive_read_role_error(request)
    if role_error:
        return role_error
    scope = authorized_node_scope(request, project_id)
    export_id = archive_package_export_id(project_id)
    rows = archive_package_rows(project_id, scope)
    reports = [repo.clone(item) for item in readable_project_reports(request, project_id, scope)]
    export_tasks = [
        repo.clone(item)
        for item in repo.state.get("export_tasks", [])
        if item.get("projectId") == project_id and scope_error_for_record(request, item, project_id) is None
    ]
    manifest = {
        "schemaVersion": "aicheck-archive-package-v2",
        "generatedAt": server_time(),
        "exportId": export_id,
        "exportType": "archive-package",
        "projectId": project_id,
        "visibility": "node-scoped" if scope is not None else "project",
        "nodeScope": sorted(scope) if scope is not None else None,
        "counts": {
            "archiveItems": len(rows),
            "reports": len(reports),
            "exportTasks": len(export_tasks),
        },
        "contents": [
            "manifest.json",
            "archive_items.json",
            "archive_items.csv",
            "reports.json",
            "export_tasks.json",
            "README.txt",
        ],
    }
    manifest["manifestHash"] = stable_hash_payload(manifest)
    body = build_archive_zip_artifact(
        manifest=manifest,
        files={
            "archive_items.json": rows,
            "archive_items.csv": package_csv(rows, ["id", "name", "type", "nodeId", "status", "updatedAt"]),
            "reports.json": reports,
            "export_tasks.json": export_tasks,
        },
    )
    existing_task = repo.find_one("export_tasks", export_id)
    task = existing_task or {
        "id": export_id,
        "projectId": project_id,
        "exportType": "archive-package",
        "status": "排队中",
        "progress": 0,
        "fileName": f"{project_id}-归档资料包.zip",
        "fileSize": 0,
        "createdAt": server_time(),
    }
    if not existing_task:
        repo.state["export_tasks"].insert(0, task)
    task["status"] = "可下载"
    task["progress"] = 100
    task["finishedAt"] = server_time()
    task["updatedAt"] = task["finishedAt"]
    task["manifest"] = manifest
    task["manifestHash"] = manifest["manifestHash"]
    repo.attach_export_artifact(task, content_type="application/zip", body=body)
    return ok({**repo.signed_get(task["fileName"], task["downloadUrl"], "application/zip", task.get("fileSize")), "exportId": export_id, "projectId": project_id, "packageType": "archive", "itemCount": len(rows), "generatedAt": task["finishedAt"], "manifest": manifest, "manifestHash": manifest["manifestHash"]}, request)


@router.get("/projects/{project_id}/archive/evidence-package")
def evidence_package(request: Request, project_id: str, nodeId: int | None = None, reportId: str | None = None):
    scope = authorized_node_scope(request, project_id)
    if nodeId is None and not reportId:
        return fail(errors.VALIDATION_ERROR, request, message="导出证据定位包必须显式传 nodeId 或 reportId。")
    report = repo.find_one("reports", reportId) if reportId else None
    if reportId and (not report or report.get("projectId") != project_id):
        return fail(errors.NOT_FOUND, request)
    effective_node_ids = [int(nodeId)] if nodeId is not None else [int(item) for item in (report or {}).get("nodeIds") or []]
    if scope is not None and (not effective_node_ids or not set(effective_node_ids).issubset(scope)):
        return fail(errors.FORBIDDEN, request, message="用户不在该节点授权范围内。")
    scope_key = reportId or f"node-{nodeId}"
    export_id = evidence_package_export_id(project_id, scope_key)
    file_name = f"{project_id}-{reportId or '节点' + str(nodeId)}-证据定位包.zip"
    evidence_rows = evidence_package_rows(project_id, node_id=nodeId, report_id=reportId)
    related_version_ids = sorted(
        {
            str(item.get("documentVersionId") or item.get("objectId"))
            for item in evidence_rows
            if item.get("documentVersionId") or item.get("objectId")
        }
    )
    manifest = {
        "schemaVersion": "aicheck-evidence-package-v2",
        "generatedAt": server_time(),
        "exportId": export_id,
        "exportType": "evidence-package",
        "projectId": project_id,
        "nodeId": nodeId,
        "reportId": reportId,
        "nodeIds": effective_node_ids,
        "counts": {
            "evidenceLinks": len(evidence_rows),
            "documentVersions": len(related_version_ids),
        },
        "documentVersionIds": related_version_ids,
        "contents": [
            "manifest.json",
            "evidence_links.json",
            "evidence_links.csv",
            "README.txt",
        ],
    }
    manifest["manifestHash"] = stable_hash_payload(manifest)
    body = build_archive_zip_artifact(
        manifest=manifest,
        files={
            "evidence_links.json": evidence_rows,
            "evidence_links.csv": package_csv(
                evidence_rows,
                ["id", "objectType", "documentId", "documentVersionId", "fileName", "pageNo", "fieldName", "quotedText", "confidence"],
            ),
        },
    )
    task = repo.find_one("export_tasks", export_id) or {"id": export_id, "projectId": project_id, "exportType": "evidence-package", "status": "排队中", "progress": 0, "fileName": file_name, "fileSize": 0, "createdAt": server_time()}
    if not repo.find_one("export_tasks", export_id):
        repo.state["export_tasks"].insert(0, task)
    task["status"] = "可下载"
    task["progress"] = 100
    task["finishedAt"] = server_time()
    task["updatedAt"] = task["finishedAt"]
    task["nodeId"] = nodeId
    task["reportId"] = reportId
    task["manifest"] = manifest
    task["manifestHash"] = manifest["manifestHash"]
    repo.attach_export_artifact(task, content_type="application/zip", body=body)
    return ok({**repo.signed_get(file_name, task["downloadUrl"], "application/zip", task.get("fileSize")), "exportId": export_id, "projectId": project_id, "packageType": "evidence", "itemCount": len(evidence_rows), "generatedAt": task["finishedAt"], "manifest": manifest, "manifestHash": manifest["manifestHash"]}, request)


@router.get("/projects/{project_id}/archive/{archive_item_id}")
def archive_item_detail(request: Request, project_id: str, archive_item_id: str):
    item = repo.find_one("archive_items", archive_item_id)
    if not item or item.get("projectId") != project_id:
        return fail(errors.NOT_FOUND, request)
    scope = authorized_node_scope(request, project_id)
    if not archive_visible_in_scope(item, scope):
        return fail(errors.FORBIDDEN, request, message="用户不在该资源授权范围内。")
    download_url = str(item.get("downloadUrl") or "").strip()
    if not download_url:
        return fail(errors.EXPORT_TASK_NOT_READY, request, message="归档项缺少可验证的文件产物。")
    report = repo.find_one("reports", str(item.get("reportId") or "")) if item.get("type") == "report" else None
    evidence_links = report_evidence_links(report) if report else []
    return ok(
        {
            "item": repo.clone(item),
            "preview": {**repo.signed_get(item["name"], download_url, item.get("contentType") or "application/pdf", item.get("fileSize")), "previewType": "pdf", "readonly": True, "pageCount": None},
            "download": repo.signed_get(item["name"], download_url, item.get("contentType"), item.get("fileSize")),
            "report": repo.clone(report) if report else None,
            "document": None,
            "evidenceLinks": evidence_links,
            "relatedExportTasks": [repo.clone(task) for task in repo.state["export_tasks"] if task.get("projectId") == project_id and task.get("reportId") == item.get("reportId")],
        },
        request,
    )


