@router.post("/projects/{project_id}/ndt/records/import")
def import_ndt_records(request: Request, project_id: str, body: dict[str, Any] = Body(default_factory=dict), idempotency_key: str | None = Header(default=None, alias="Idempotency-Key"), x_role: str | None = Header(default=None, alias="X-Role")):
    node_ids = node_ids_from_body(body, 40)

    def produce():
        guard = mutation_guard(request, project_id, x_role=x_role, node_ids=node_ids)
        if guard:
            return guard
        actor_role, identity_error = effective_role_for_request(request, x_role)
        if identity_error:
            return identity_error
        actor_member = active_project_member_for_request(request, project_id, actor_role)
        rows = body.get("rows") or []
        if not rows:
            return fail(errors.NDT_RECORD_REQUIRED, request, message="导入检测记录行不能为空。")
        required_fields = ["recordNo", "weldNo", "method"]
        failed = [
            {"row": index + 1, "fields": missing_required_fields(row, required_fields)}
            for index, row in enumerate(rows)
            if missing_required_fields(row, required_fields)
        ]
        if failed:
            return fail(errors.NDT_RECORD_REQUIRED, request, data={"failed": failed})
        for index, row in enumerate(rows):
            candidate = {
                "id": f"NDT-REC-VALIDATE-{index + 1}",
                "projectId": project_id,
                "nodeId": node_ids[0] if node_ids else 40,
                "sourceOrgId": (actor_member or {}).get("orgId"),
                "sourceOrgName": (actor_member or {}).get("orgName"),
                **{
                    field: row.get(field)
                    for field in NDT_RECORD_METADATA_FIELDS
                    if row.get(field) is not None
                },
            }
            if not ndt_record_visible_for_request(request, project_id, candidate):
                return fail(
                    errors.FORBIDDEN,
                    request,
                    message="当前角色无权关联所选无损检测报告或底片。",
                    data={"row": index + 1},
                    http_status=403,
                )
        created = []
        for row in rows:
            record = {
                "id": f"NDT-REC-{uuid4().hex[:8].upper()}",
                "projectId": project_id,
                "nodeId": node_ids[0] if node_ids else 40,
                "recordNo": row.get("recordNo"),
                "weldNo": row.get("weldNo"),
                "method": row.get("method"),
                "sourceOrgId": (actor_member or {}).get("orgId"),
                "sourceOrgName": (actor_member or {}).get("orgName"),
                "testDate": row.get("testDate"),
                "evaluatorName": row.get("evaluatorName"),
                "result": row.get("result") or "待复核",
                "sampleStatus": row.get("sampleStatus") or "未抽查",
                "qualityStatus": "完整" if row.get("testDate") and row.get("evaluatorName") else "需补充",
                "missingFields": missing_required_fields(row, ["testDate", "evaluatorName"]),
                "importedAt": server_time(),
                "actions": ["ndt:record-import"],
            }
            record.update({field: row.get(field) for field in NDT_RECORD_METADATA_FIELDS if row.get(field) is not None})
            repo.state["ndt_records"].insert(0, record)
            created.append(record)
        return ok({"imported": len(created), "failed": [], "records": created}, request)

    return idempotent(
        request,
        idempotency_key,
        produce,
        fingerprint_source={"projectId": project_id, "body": body},
    )


