@router.get("/reasoning/logs")
def reasoning_logs(request: Request, projectId: str | None = None, nodeId: int | None = None, status: str | None = None, page_no: int = Query(default=1, alias="page"), page_size: int = Query(default=20, alias="pageSize")):
    # 与 /nodes/{n}/ai-runs 用同一道闸。
    #
    # 2026-08-14 审计实测：这里只做了项目范围过滤（record_visible_for_request），
    # 没有角色闸，于是施工方能读到本项目里监检方的 AI 判定——
    # suggestion.result、opinionDraft、reasoningProcess 一应俱全。
    # 而同样的数据在 /nodes/{n}/ai-runs 上是 403。
    #
    # 一道门拦住、另一道敞着，等于没拦。返回的是同一个 ai_runs 集合，
    # 守卫也就该是同一个，别再各写各的。
    process_error = review_process_read_error(request, "AI 推理过程记录")
    if process_error:
        return process_error
    items = [repo.clone(item) for item in repo.state["ai_runs"] if record_visible_for_request(request, item)]
    if projectId:
        items = [item for item in items if item["projectId"] == projectId]
    if nodeId:
        items = [item for item in items if int(item["nodeId"]) == int(nodeId)]
    if status:
        items = [item for item in items if item["status"] == status]
    return ok(page(items, page_no, page_size), request)


def ai_run_evidence_snapshot(run: dict[str, Any]) -> list[dict[str, Any]]:
    embedded = [item for item in (run.get("evidenceLinks") or []) if isinstance(item, dict)]
    if embedded:
        return repo.clone(embedded)
    evidence_ids = {
        str(item)
        for item in (run.get("evidenceLinkIds") or [])
        if item
    }
    if not evidence_ids:
        return []
    project_id = str(run.get("projectId") or "")
    node_id = int(run.get("nodeId") or 0)
    candidates = [*repo.state.get("node_evidence_links", []), *repo.state.get("evidence_links", [])]
    return repo.clone(
        [
            item
            for item in candidates
            if str(item.get("id") or "") in evidence_ids
            and item.get("projectId") == project_id
            and int(item.get("nodeId") or node_id) == node_id
        ]
    )


@router.get("/reasoning/logs/{log_id}")
def reasoning_log_detail(request: Request, log_id: str):
    # 同 /reasoning/logs：这是 ai_runs 的另一个入口，守卫必须一致。
    process_error = review_process_read_error(request, "AI 推理过程记录")
    if process_error:
        return process_error
    run = repo.find_one("ai_runs", log_id)
    if not run:
        return fail(errors.NOT_FOUND, request)
    scope_error = scope_error_for_record(request, run)
    if scope_error:
        return scope_error
    review_run_id = run.get("reviewRunId")
    graph_nodes = [
        repo.clone(item)
        for item in repo.state.get("review_graph_nodes", [])
        if review_run_id and item.get("reviewRunId") == review_run_id
    ]
    trace_steps = [
        repo.clone(item)
        for item in repo.state.get("ai_trace_steps", [])
        if item.get("aiRunId") == log_id
    ]
    trace_steps.sort(key=lambda item: int(item.get("sequence") or 0))
    graph_nodes.sort(key=lambda item: int(item.get("sequence") or 0))
    raw = has_raw_access(request, "ai_run", log_id)
    llm_audit = fde_llm_audit_view(run, run_type="ai_run", raw_access=raw, trace_steps=trace_steps)
    return ok(
        {
            "log": fde_ai_run_view(run, raw_access=raw),
            "evidenceLinks": ai_run_evidence_snapshot(run),
            "traceSteps": trace_steps,
            "graphNodes": graph_nodes,
            "promptAudit": repo.clone(llm_audit["inputs"]),
            "llmMetadata": repo.clone(llm_audit["metadata"]),
            "llmAudit": llm_audit,
            "accessPolicy": {"rawAccess": raw, "rawAccessRequiresGrant": not raw},
        },
        request,
    )


